          var a0x = aesXtime(a0), a1x = aesXtime(a1), a2x = aesXtime(a2), a3x = aesXtime(a3);
          s[c3 * 4]     = a0x ^ a1x ^ a1 ^ a2 ^ a3;
          s[c3 * 4 + 1] = a0 ^ a1x ^ a2x ^ a2 ^ a3;
          s[c3 * 4 + 2] = a0 ^ a1 ^ a2x ^ a3x ^ a3;
