// ---- 纯 JS SHA-1（A2 稳定 id；Hermes 沙箱无 crypto 模块，手写实现）----
function utf8Bytes(str) {
  var out = [];
  var s = String(str);
  for (var i = 0; i < s.length; i++) {
    var c = s.charCodeAt(i);
    if (c < 0x80) {
      out.push(c);
    } else if (c < 0x800) {
      out.push(0xC0 | (c >> 6), 0x80 | (c & 0x3F));
    } else if (c >= 0xD800 && c <= 0xDBFF && i + 1 < s.length) {
      var c2 = s.charCodeAt(i + 1);
      if (c2 >= 0xDC00 && c2 <= 0xDFFF) {
        var cp = 0x10000 + ((c - 0xD800) << 10) + (c2 - 0xDC00);
        out.push(0xF0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3F), 0x80 | (cp & 0x3F));
        i++;
      } else {
        out.push(0xEF, 0xBF, 0xBD); // 孤立高位代理 → U+FFFD
      }
    } else if (c >= 0xD800 && c <= 0xDFFF) {
      out.push(0xEF, 0xBF, 0xBD);
    } else {
      out.push(0xE0 | (c >> 12), 0x80 | ((c >> 6) & 0x3F), 0x80 | (c & 0x3F));
    }
  }
  return out;
}

function sha1Hex(msg) {
  var bytes = utf8Bytes(msg);
  var bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  var hi = Math.floor(bitLen / 4294967296);
  var lo = bitLen - hi * 4294967296;
  var i;
  for (i = 3; i >= 0; i--) bytes.push((hi >>> (8 * i)) & 0xFF);
  for (i = 3; i >= 0; i--) bytes.push((lo >>> (8 * i)) & 0xFF);

  var H = [0x67452301 | 0, (0xEFCDAB89 | 0), (0x98BADCFE | 0), (0x10325476 | 0), (0xC3D2E1F0 | 0)];
  function rol(n, b) { return ((n << b) | (n >>> (32 - b))) | 0; }
  for (var off = 0; off < bytes.length; off += 64) {
    var w = new Array(80);
    for (i = 0; i < 16; i++) {
      w[i] = ((bytes[off + 4 * i] << 24) | (bytes[off + 4 * i + 1] << 16) |
              (bytes[off + 4 * i + 2] << 8) | bytes[off + 4 * i + 3]) | 0;
    }
    for (i = 16; i < 80; i++) w[i] = rol(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    var a = H[0], b = H[1], c = H[2], d = H[3], e = H[4];
    for (i = 0; i < 80; i++) {
      var f, k;
      if (i < 20) { f = (b & c) | (~b & d); k = 0x5A827999 | 0; }
      else if (i < 40) { f = b ^ c ^ d; k = 0x6ED9EBA1 | 0; }
      else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8F1BBCDC | 0; }
      else { f = b ^ c ^ d; k = 0xCA62C1D6 | 0; }
      var t = (rol(a, 5) + f + e + k + w[i]) | 0;
      e = d; d = c; c = rol(b, 30); b = a; a = t;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0;
    H[3] = (H[3] + d) | 0; H[4] = (H[4] + e) | 0;
  }
  var out = '';
  for (i = 0; i < 5; i++) {
    var v = H[i] >>> 0;
    for (var j = 7; j >= 0; j--) out += ((v >>> (4 * j)) & 0xF).toString(16);
  }
  return out;
}

