// ---- FinalItem 合并构建（§4.2 / §5.2 A2）----
function buildMergedFinalItem(members, sessionId) {
  // 桶内呈现序：源序优先（口径③），同源按收录序
  var sorted = members.slice().sort(function (a, b) {
    var d = srcRankOf(a.srcKey) - srcRankOf(b.srcKey);
    return d !== 0 ? d : a.seq - b.seq;
  });
  var def = sorted[0]; // _default = 源序第一个有结果的源（酷我优先）
  var srcMap = {};
  var i;
  for (i = 0; i < sorted.length; i++) {
    if (!srcMap[sorted[i].srcKey]) srcMap[sorted[i].srcKey] = freezeSnapshot(sorted[i].raw);
  }
  var variants = [];
  for (i = 0; i < sorted.length; i++) {
    // _variants 保留全部成员快照（含默认首条；同源重复条目在此共存，_src 各源只留首条）
    variants.push({ srcKey: sorted[i].srcKey, item: freezeSnapshot(sorted[i].raw) });
  }
  // §8.3（v0.3.0 并入）：跨源动态 qualities —— 逐源做「宿主支持 ∩ 该源声明」交集门，
  // 首见档位定 size（呈现序=酷我优先），_qualitySources 聚合全部声明源（口径③顺序）
  var qu = {};
  var qSrcAll = {};
  for (i = 0; i < sorted.length; i++) {
    var hostQs = SOURCE_HOST_QUALITIES[sorted[i].srcKey] || [];
    var rawQ = (sorted[i].raw.qualities && typeof sorted[i].raw.qualities === 'object') ? sorted[i].raw.qualities : {};
    for (var qi = 0; qi < hostQs.length; qi++) {
      var qk = hostQs[qi];
      var qv = rawQ[qk];
      if (!qv || typeof qv !== 'object') continue;
      if (!qu[qk]) {
        qu[qk] = {
          size: parseSizeToBytes(qv.size),
          bitrate: qv.bitrate !== undefined ? qv.bitrate : null,
          format: qv.format !== undefined ? qv.format : null
        };
      }
      var srcList = qSrcAll[qk] || (qSrcAll[qk] = []);
      srcList.push(sorted[i].srcKey);
    }
  }
  // S3（v0.4.1 并入）：宿主跳转字段透传（singerList/albumid/albumId/album_id/artistId 等）。
  // 以 _default 源快照为准（跨源时歌手/专辑归属随默认源），固定键与 '_' 内部键不受影响。
  // v0.8.0 补丁（真网冒烟发现）：全部参与源均无 qualities 元数据时（榜单/歌单详情等
  // vendor 接口常缺），不挂空声明表——空表会让 aggQualityAvailable 的「声明表存在但
  // 该档未声明」分支挡死矩阵兜底，宿主任何档位都取不到（榜单内歌曲无法播放）。
  // 保持 _qualitySources 缺失 → 走矩阵兜底防御路径（与 v0.2.0 时代静态矩阵语义一致，
  // 实际档位由调度器大小校验 + 宁低勿高 actualQuality 兜住）。
  var hasQDecl = false;
  for (var qk0 in qSrcAll) { if (qSrcAll[qk0] && qSrcAll[qk0].length) { hasQDecl = true; break; } }
  // [v1.3.2 F5] 音质标识兜底：交集门后无任何 badge 档位（128k~hires）时补最低档
  // 128k 显示档；无元数据源同步按全矩阵补路由表（取链面不回退）。调用后声明表
  // 必非空 → hasQDecl 恒为 true。
  (function () {
    var mk = [];
    for (var mi = 0; mi < sorted.length; mi++) {
      if (mk.indexOf(sorted[mi].srcKey) < 0) mk.push(sorted[mi].srcKey);
    }
    ensureMinQualityBadge(qu, qSrcAll, mk);
    hasQDecl = true;
  })();
  // v1.3.0（分类聚合封面修复）：合并组封面跨成员回退——默认源缺封面而次源有时，
  // 旧逻辑直接丢封面（分类条目封面是主视觉；music 同样受益）。按呈现序依次取
  // 任一成员的 coverImg / cover / artwork 非空值。
  var coverFallback;
  for (i = 0; i < sorted.length; i++) {
    var cr = sorted[i].raw;
    var cv = cr.coverImg !== undefined ? cr.coverImg : (cr.cover !== undefined ? cr.cover : cr.artwork);
    if (cv !== undefined && cv !== null && cv !== '') { coverFallback = cv; break; }
  }
  var fi = {
    id: 'agg' + sha1Hex(def.srcKey + ':' + String(def.raw.id)),
    title: def.raw.title,
    artist: def.raw.artist,
    album: def.raw.album,
    duration: def.duration,
    coverImg: coverFallback,
    platform: 'agg',
    primaryKey: ['id'],
    qualities: qu,        // §8.3：跨源动态档位（size 归一字节，首见源定值）
    _src: srcMap,
    _srcOrder: AGG_SOURCE_ORDER,
    _default: def.srcKey,
    _variants: variants,
    _session: sessionId || null
  };
  if (hasQDecl) fi._qualitySources = qSrcAll; // §8.3：逐档路由表（全部声明源，口径③顺序）
  // v1.0.0 D1：MV 标识聚合（跨源合并组）——默认源无 MV 而次源有时标识会丢，
  // 必须显式聚合（passThroughExtras 只透默认源字段）
  return applyMvAggregation(passThroughExtras(fi, def.raw));
}

// ---- AggSession（§5.1/§5.4 + A1）----
function sessionKeyOf(keyword, type) {
  return String(type || 'music') + '\u0003' + String(keyword == null ? '' : keyword);
}
var _aggSessions = []; // LRU：新会话 unshift 到头部，超过上限 pop 尾部

function sessionTtlMs() {
  return _aggTestOverrides.sessionTtlMs != null ? _aggTestOverrides.sessionTtlMs : AGG_SESSION_TTL_MS;
}
function isSessionExpired(s) {
  return Date.now() - s.createdAt > sessionTtlMs();
}
function sessionGet(key) {
  for (var i = 0; i < _aggSessions.length; i++) {
    if (_aggSessions[i].key === key) {
      var s = _aggSessions[i];
      if (i > 0) { _aggSessions.splice(i, 1); _aggSessions.unshift(s); }
      return s;
    }
  }
  return null;
}
function sessionPut(s) {
  for (var i = 0; i < _aggSessions.length; i++) {
    if (_aggSessions[i].key === s.key) { _aggSessions.splice(i, 1); break; }
  }
  _aggSessions.unshift(s);
  while (_aggSessions.length > AGG_SESSION_MAX) _aggSessions.pop();
}
function createAggSession(keyword, type) {
  return {
    key: sessionKeyOf(keyword, type),
    keyword: keyword,
    type: type,
    createdAt: Date.now(),
    allDone: false,
    itemSeq: [],
    sourceState: {},
    intent: null,
    intentFolded: '',
    stats: { rawCount: 0, groupCount: 0, mergedCount: 0, singleCount: 0, dedupSaved: 0, capped: false, absentSources: [] }
  };
}

// 单源超时包装：超时/异常均不抛出，以标记对象返回（缺席语义）
function aggWithTimeout(promise, ms) {
  return new Promise(function (resolve) {
    var settled = false;
    var timer = setTimeout(function () {
      if (!settled) { settled = true; resolve({ __timeout: true }); }
    }, Math.max(ms, 0));
    Promise.resolve(promise).then(function (v) {
      if (!settled) { settled = true; clearTimeout(timer); resolve({ __value: v }); }
    }, function (e) {
      if (!settled) { settled = true; clearTimeout(timer); resolve({ __error: e }); }
    });
  });
}

// 拉单源首轮（v1.3.0 并行翻页版）。
// 旧版在预算内逐页串行翻到 isEnd（最多 40 页），慢源串行数十次请求把整体拖到 5-8s——
// 这是聚合搜索耗时的主瓶颈。新版：页1先行（命中 isEnd 即单跳收工）；未结束时页 2..N
// 一次并发（N = searchMaxPages，默认 3），按页序拼接、首个 isEnd 页之后的页丢弃；
// 页 k≥2 超时/失败仅截断该源（保留已有页），不算缺席；页1失败才整源缺席。
// 单源整体仍受预算 deadline 约束（每页 aggWithTimeout 以剩余预算为闸）。
// 取舍说明：首轮页数封顶会截断单源深翻页（旧版最多 40 页 × 每页 20-30 条 = 数百条/源），
// 六源 × 3 页 ≈ 200-500 条候选，聚合浏览（每页 30 条）完整性与旧版无体感差异；
// 需要更深回源时经 searchMaxPages 调大（上限仍受 AGG_SOURCE_PAGE_GUARD 护栏）。
async function pullSourceAll(session, srcKey, budgetMs) {
  var st = { ended: false, absent: false, page: 0, items: [], error: null };
  session.sourceState[srcKey] = st;
  var deadline = Date.now() + budgetMs;
  var r1 = await aggWithTimeout(callProviderSearch(srcKey, session.keyword, 1, session.type), budgetMs);
  if (r1.__timeout) { st.absent = true; return; }
  if (r1.__error) { st.absent = true; st.error = errMsg(r1.__error); return; }
  var res1 = r1.__value;
  if (res1.error) { st.absent = true; st.error = res1.error; return; }
  var rawItems = res1.items.slice();
  st.page = 1;
  if (res1.isEnd) { st.ended = true; st.items = rawItems; return; }
  var maxPages = searchMaxPagesOf();
  if (maxPages >= 2) {
    var pageNo = [], jobs = [];
    for (var pg = 2; pg <= maxPages; pg++) {
      var remaining = deadline - Date.now();
      if (remaining <= 0) break;
      pageNo.push(pg);
      jobs.push(aggWithTimeout(callProviderSearch(srcKey, session.keyword, pg, session.type), remaining));
    }
    var rs = await Promise.all(jobs);
    for (var i = 0; i < rs.length; i++) {
      var r = rs[i];
      if (r.__timeout || r.__error) break;
      var res = r.__value;
      if (res.error) break;
      rawItems = rawItems.concat(res.items);
      st.page = pageNo[i];
      if (res.isEnd) { st.ended = true; break; }
    }
  }
  if (!st.ended) st.ended = true; // 首轮页数封顶 = 源侧截断；isEnd 语义由会话层（allDone && 缓存耗尽）统一判定
  st.items = rawItems;
}

// 首轮：六源并发 → 归一化 → 分桶合并 → §6 排序 → 全量缓存
async function aggRoundOne(session) {
  var budget = searchBudgetMsOf();
  var jobs = [];
  for (var i = 0; i < AGG_SOURCE_ORDER.length; i++) {
    var k = AGG_SOURCE_ORDER[i];
    var p = __AGG_PROVIDERS[k];
    if (!aggSourceEnabled(k)) { // §14：源开关关闭 → 整源缺席（不烧预算）
      session.sourceState[k] = { ended: true, absent: true, page: 0, items: [], error: 'disabled' };
      session.stats.absentSources.push(k);
      continue;
    }
    if (!p || typeof p.search !== 'function' ||
        (Array.isArray(p.supportedSearchType) && p.supportedSearchType.indexOf(session.type) < 0)) {
      session.sourceState[k] = { ended: true, absent: true, page: 0, items: [], error: 'unsupported' };
      session.stats.absentSources.push(k);
      continue;
    }
    jobs.push(pullSourceAll(session, k, budget));
  }
  await Promise.all(jobs);
  // v1.3.0：music 走原 rebuild（版本聚合+§6 排序）；album/artist/sheet 走分类
  // rebuild（categoryAdaptRaw 适配 + 分类去重键归并 + 分类匹配度排序）。
  if (session.type === 'music') rebuildSessionItems(session);
  else rebuildSessionItemsCategory(session);
  session.allDone = true;
}

// 排序 + FinalItem 全量构建（itemSeq 每会话只在本函数内生成一次，已发出条目不可变）
function rebuildSessionItems(session) {
  var norm = [], seq = 0;
  for (var s = 0; s < AGG_SOURCE_ORDER.length; s++) {
    var srcKey = AGG_SOURCE_ORDER[s];
    var st = session.sourceState[srcKey];
    if (!st) continue;
    var arr = st.items || [];
    for (var i = 0; i < arr.length; i++) {
      var n = normalizeItem(srcKey, arr[i]);
      if (n) { n.seq = seq++; norm.push(n); }
    }
  }
  session.stats.rawCount = norm.length;
  if (norm.length > AGG_CACHE_CAP) {
    norm = norm.slice(0, AGG_CACHE_CAP);
    session.stats.capped = true;
  }
  session.intentFolded = foldWidthLower(session.keyword);
  session.intent = detectArtistIntent(session.keyword, norm);
  var groups = clusterAndMerge(norm);
  var merged = [], singles = [];
  for (var g = 0; g < groups.length; g++) {
    groups[g].sortScore = groupSortScore(groups[g], session);
    if (groups[g].members.length >= 2) merged.push(groups[g]);
    else singles.push(groups[g]);
  }
  merged.sort(function (a, b) { return b.sortScore - a.sortScore; });
  singles.sort(function (a, b) { return b.sortScore - a.sortScore; });
  var out = [];
  for (g = 0; g < merged.length; g++) out.push(buildMergedFinalItem(merged[g].members, session.key));
  for (g = 0; g < singles.length; g++) out.push(buildMergedFinalItem(singles[g].members, session.key));
  session.itemSeq = out;
  session.stats.groupCount = groups.length;
  session.stats.mergedCount = merged.length;
  session.stats.singleCount = singles.length;
  session.stats.dedupSaved = norm.length - out.length;
}

// 分页切片（§5.4）：纯缓存读，emitted 前缀天然不可变；isEnd = 全源已结束/缺席 且 缓存耗尽
function servePage(session, page) {
  var start = (page - 1) * AGG_PAGE_SIZE;
  var end = page * AGG_PAGE_SIZE;
  var data = session.itemSeq.slice(start, end);
  var cacheExhausted = session.itemSeq.length < end;
  var isEnd = session.allDone && cacheExhausted;
  return { data: data, isEnd: isEnd };
}

/**
 * 聚合搜索主入口（music 类型）。
 * A1 语义：page≤1 强制新会话（重搜即刷新）；page≥2 走既有会话缓存，
 * TTL 过期或会话被 LRU 挤出时重建会话（全量重拉）并按同一页码取数。
 * 已发出条目不可变：itemSeq 每会话只生成一次，分页只做切片。
 */
async function searchMusicAggregated(query, page, type) {
  var kw = query == null ? '' : String(query);
  if (!kw) return { data: [], isEnd: true };
  var pno = parseInt(page, 10);
  if (!(pno >= 1)) pno = 1;
  var key = sessionKeyOf(kw, type);
  var s = sessionGet(key);
  var needRound = true;
  if (pno > 1 && s && !isSessionExpired(s)) {
    needRound = false;
  } else {
    s = createAggSession(kw, type);
    sessionPut(s);
  }
  if (needRound) await aggRoundOne(s);
  return servePage(s, pno);
}

// sheet/lyric 透传（v0.2.0 契约对齐 search 返回 { data, isEnd }；合并留待后续步骤）
function searchPassthrough(query, page, type) {
  var t = type || 'sheet';
  var jobs = [];
  for (var i = 0; i < AGG_SOURCE_ORDER.length; i++) {
    var k = AGG_SOURCE_ORDER[i];
    var p = __AGG_PROVIDERS[k];
    if (!aggSourceEnabled(k)) continue; // §14：源开关关闭 → 透传不拉该源
    if (!p || typeof p.search !== 'function') continue;
    if (Array.isArray(p.supportedSearchType) && p.supportedSearchType.indexOf(t) < 0) continue;
    jobs.push(callProviderSearch(k, query, page, t));
  }
  if (!jobs.length) return Promise.resolve({ data: [], isEnd: true });
  return Promise.all(jobs).then(function (results) {
    var out = [];
    var any = false, allEnd = true;
    for (var r = 0; r < results.length; r++) {
      var res = results[r];
      any = true;
      if (!res.isEnd) allEnd = false;
      if (res.error) consoleWarn('[agg] search ' + res.key + ' 失败: ' + res.error);
      var items = res.items;
      for (var n = 0; n < items.length; n++) {
        var fi = buildFinalItem(res.key, items[n]);
        if (fi) out.push(fi);
      }
    }
    return { data: out, isEnd: any ? allEnd : true };
  });
}

// ---- v1.3.0 分类聚合搜索（album / artist / sheet）----
// 六源并发拉取（与 music 同一首轮链路）→ 按分类去重合并 → 匹配度排序 → AggSession 分页。
// 去重键（分类语义不同，键不同）：
//   album  = 归一化专辑名 + 歌手集合键（同名专辑不同歌手不并）
//   artist = 归一化歌手名
//   sheet  = 归一化歌单标题 + 创建者集合键（同名歌单不同创建者不并）
// vendor 条目形态适配（源侧字段 → 归一化所需字段）：
//   album/sheet：name 在 title、封面在 artwork；artist：name 在 name、封面在 avatar。
//   适配为浅拷贝新增 title/artist/coverImg 视图字段，源侧原字段（artwork/avatar/
//   albumid/artistId/_asrc/_ssrc 等）原样保留（passThroughExtras 继续透传给宿主）。
function categoryAdaptRaw(type, raw) {
  if (!raw || typeof raw !== 'object') return raw;
  if (type === 'artist') {
    var cp = Object.assign({}, raw);
    if (cp.title === undefined && cp.name !== undefined) cp.title = cp.name;
    if (cp.artist === undefined && cp.name !== undefined) cp.artist = cp.name;
    if (cp.coverImg === undefined && cp.avatar !== undefined) cp.coverImg = cp.avatar;
    return cp;
  }
  if (raw.coverImg === undefined && raw.artwork !== undefined) {
    var cp2 = Object.assign({}, raw);
    cp2.coverImg = raw.artwork;
    return cp2;
  }
  return raw;
}

// 簇主导字段：众数（并列取更短者）——跨桶合并簇的代表 coreTitle/artistKey 可能带
// 符号/不可见字符差异（实测 kugou '周杰伦.' 与 kuwo '周杰伦' 各成一簇），members[0]
// 取代表不稳定，众数才是簇的真实身份。
function dominantValueOf(members, field) {
  var cnt = {}, best = '', bestN = -1;
  for (var i = 0; i < members.length; i++) {
    var t = String(members[i][field] == null ? '' : members[i][field]);
    cnt[t] = (cnt[t] || 0) + 1;
    if (cnt[t] > bestN || (cnt[t] === bestN && t.length < best.length)) { bestN = cnt[t]; best = t; }
  }
  return best;
}

// 去重键折叠：仅保留字母数字与中日韩统一表意文字，剥离符号/空白/零宽字符等
// 显示不可见差异（'周杰伦.' → '周杰伦'）；全被剥空时回退原键。
function categoryKeyFoldOf(s) {
  var f = String(s == null ? '' : s).replace(/[^a-z0-9一-龥]+/g, '');
  return f || String(s == null ? '' : s);
}

function categoryDedupKeyOf(type, n) {
  if (type === 'artist') return n.coreTitle;
  return n.coreTitle + '\u0003' + (n.artistKey || '');
}

function categoryGroupScore(group, session) {
  var rep = groupRep(group.members);
  return 0.60 * groupMatchScore(rep, session)
       + 0.25 * groupCoverageScore(group.members)
       + 0.15 * (1 - srcRankOf(rep.srcKey) / AGG_SOURCE_ORDER.length);
}

function rebuildSessionItemsCategory(session) {
  var norm = [], seq = 0;
  for (var s = 0; s < AGG_SOURCE_ORDER.length; s++) {
    var srcKey = AGG_SOURCE_ORDER[s];
    var st = session.sourceState[srcKey];
    if (!st) continue;
    var arr = st.items || [];
    for (var i = 0; i < arr.length; i++) {
      var n = normalizeItem(srcKey, categoryAdaptRaw(session.type, arr[i]));
      if (n) { n.seq = seq++; norm.push(n); }
    }
  }
  session.stats.rawCount = norm.length;
  session.intentFolded = foldWidthLower(session.keyword);
  session.intent = detectArtistIntent(session.keyword, norm);
  // 先走 music 同款分桶合并（同源重复/跨源同键收敛），再按分类去重键二次归并。
  // v1.3.0 归并键三级收敛：①簇代表字段取众数（dominantValueOf——跨桶合并簇内
  // members[0] 不稳定，实测 kugou '周杰伦.' 与 kuwo '周杰伦' 各成一簇）；
  // ②符号折叠（categoryKeyFoldOf，'周杰伦.'→'周杰伦'）精确归并；
  // ③同首字符桶内 editDistSim≥0.90 模糊归并（只比同桶，避免 O(K²) 全量编辑距离）。
  var groups = clusterAndMerge(norm);
  var accepted = [];   // { key, members }：折叠键 → 归并簇
  var exact = {};      // 折叠键 → accepted 下标（精确命中短路）
  var byFirst = {};    // 折叠键首字符 → accepted 下标数组（模糊归并分桶）
  for (var g = 0; g < groups.length; g++) {
    var mem = groups[g].members;
    var fkey = categoryKeyFoldOf(categoryDedupKeyOf(session.type, {
      coreTitle: dominantValueOf(mem, 'coreTitle'),
      artistKey: dominantValueOf(mem, 'artistKey')
    }));
    var fc = fkey.charAt(0) || '#';
    var target = exact[fkey];
    if (target === undefined) {
      var cand = byFirst[fc] || [];
      for (var c = 0; c < cand.length; c++) {
        if (editDistSim(fkey, accepted[cand[c]].key) >= 0.90) { target = cand[c]; break; }
      }
      if (target === undefined) {
        target = accepted.length;
        accepted.push({ key: fkey, members: [] });
      }
      exact[fkey] = target;
      (byFirst[fc] || (byFirst[fc] = [])).push(target);
    }
    accepted[target].members = accepted[target].members.concat(mem);
  }
  var scored = [];
  for (g = 0; g < accepted.length; g++) {
    scored.push({ members: accepted[g].members, score: categoryGroupScore({ members: accepted[g].members }, session) });
  }
  scored.sort(function (a, b) { return b.score - a.score; });
  var finals = [];
  for (g = 0; g < scored.length; g++) finals.push(buildMergedFinalItem(scored[g].members, session.key));
  session.itemSeq = finals;
  session.stats.groupCount = accepted.length;
  session.stats.mergedCount = 0;
  session.stats.singleCount = 0;
  session.stats.dedupSaved = norm.length - finals.length;
}

// 分类聚合主入口：A1 会话语义与 music 一致（page≤1 新会话，page≥2 走缓存切片），
// 会话键含 type（sessionKeyOf），music/album/artist/sheet 互不串缓存。
async function searchCategoryAggregated(query, page, type) {
  var kw = query == null ? '' : String(query);
  if (!kw) return { data: [], isEnd: true };
  var pno = parseInt(page, 10);
  if (!(pno >= 1)) pno = 1;
  var key = sessionKeyOf(kw, type);
  var s = sessionGet(key);
  var needRound = true;
  if (pno > 1 && s && !isSessionExpired(s)) {
    needRound = false;
  } else {
    s = createAggSession(kw, type);
    sessionPut(s);
  }
  if (needRound) await aggRoundOne(s);
  return servePage(s, pno);
}

// §8 音质统一映射（QualityMapping）（v0.3.0 并入）

// 六源对宿主标准档位的支持矩阵（与各 vendor supportedQualities 声明一致；
// §8.2 档位并集：最终插件声明六源并集，逐档路由按本矩阵回退）
var SOURCE_HOST_QUALITIES = {
  kuwo:    ['128k', '192k', '320k', 'flac', 'hires', 'master', 'atmos'],
  migu:    ['128k', '320k', 'flac', 'flac24bit', 'hires', 'atmos', 'atmos_plus'],
  netease: ['128k', '192k', '320k', 'flac', 'flac24bit', 'hires', 'atmos', 'master', 'dolby'],
  // v1.1.0 工单四（甲案·聚合层修）：qishui v1.7.0 的酷我兜底臂已由构建补丁
  // qishui-strip-fallback 剥离（重建产物逐字节比对一致），其 192k/320k/flac 系
  // 「借兜底臂成立」的档位——剥离后不再成立。聚合归一化层对汽水只认 128k：
  // buildFinalItem/buildMergedFinalItem 的 qualities 交集门、aggQualityAvailable
  // 档位门、buildCandidates 矩阵兜底与 doctor 报告均以本表为准，汽水不再虚假
  // 在册于 320k/flac 等路由表（不陪跑竞速烧窗口、不污染健康度）。
  qishui:  ['128k'],
  kugou:   ['128k', '192k', '320k', 'flac', 'flac24bit', 'hires', 'atmos', 'master'],
  qq:      ['128k', '192k', '320k', 'flac', 'flac24bit']
};

// 各源档位参数映射（§8.1）：宿主标准档位 → 传给 provider.getMediaSource 的档位参数。
// 六源 vendor 均直接接受宿主标准档名（内部再映射到各自原生档，如网易云
// standard/higher/exhigh/lossless/hires、咪咕 PQ/HQ/SQ/ZQ24/Z3D——映射在
// provider 内部完成，聚合层不做二次翻译），因此本表当前为恒等映射；
// 保留表结构是为后续接入需换名的源/代理通道时不动调度器。
var QUALITY_TIER_MAP = {
  kuwo:    { '128k': '128k', '192k': '192k', '320k': '320k', 'flac': 'flac', 'hires': 'hires', 'master': 'master', 'atmos': 'atmos' },
  migu:    { '128k': '128k', '320k': '320k', 'flac': 'flac', 'flac24bit': 'flac24bit', 'hires': 'hires', 'atmos': 'atmos', 'atmos_plus': 'atmos_plus' },
  netease: { '128k': '128k', '192k': '192k', '320k': '320k', 'flac': 'flac', 'flac24bit': 'flac24bit', 'hires': 'hires', 'atmos': 'atmos', 'master': 'master', 'dolby': 'dolby' },
  // v1.1.0 工单四：与 SOURCE_HOST_QUALITIES.qishui 同步收敛（兜底臂已剥离，仅主链 128k）
  qishui:  { '128k': '128k' },
  kugou:   { '128k': '128k', '192k': '192k', '320k': '320k', 'flac': 'flac', 'flac24bit': 'flac24bit', 'hires': 'hires', 'atmos': 'atmos', 'master': 'master' },
  qq:      { '128k': '128k', '192k': '192k', '320k': '320k', 'flac': 'flac', 'flac24bit': 'flac24bit' }
};

function qualityParamOf(srcKey, quality) {
  var map = QUALITY_TIER_MAP[srcKey];
  if (map && map[quality] !== undefined) return map[quality];
  return quality;
}

// §7.2/B1 六源大小接口对照表（文档化：标称大小的主来源是 provider 在 search/
// getMusicInfo 时回填的 item.qualities[q].size——各源 provider 内部已对接其大小接口；
// 聚合层在 qualities 缺失时以 getMusicInfo 兜底（1s 预算 + NOMINAL_CACHE））：
//   kuwo    搜索/详情 N_MINFO 字段，字符串 "178.32MB" 口径为 MiB（1024 进制，
//           178.32MB ↔ 186,980,254 字节实证），parseSizeToBytes 按 1024 进制解析
//   migu    搜索条目 qualities；详情走 by-contentids（fetchMiguSongMeta）回填
//   netease cloudsearch/song 条目 qualities（provider 已回填 size 字节值）
//   qishui  track.php 返回 qualities（size 字节值；flac 档存在虚标 → 靠校验拦截）
//   kugou   搜索 hash 条目 qualities；getSongInfo.php 详情回填（仅免费 128k）
//   qq      search 条目 qualities（size 字节值；加密档 ekey 链路走豁免分支）

// 大小字符串 → 字节数。数字直返；"178.32MB"/"1.2GB"/"320K" 按 1024 进制（MiB 口径）；
// 纯数字字符串按字节。解析失败返回 null。
function parseSizeToBytes(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number' && isFinite(v) && v >= 0) return Math.round(v);
  var s = String(v).trim();
  if (!s) return null;
  var m = s.match(/^(\d+(?:\.\d+)?)\s*([kKmMgGtT]?)[bB]?$/);
  if (!m) {
    var n = Number(s);
    return (isFinite(n) && n >= 0) ? Math.round(n) : null;
  }
  var num = parseFloat(m[1]);
  var unit = m[2].toUpperCase();
  var mult = unit === 'K' ? 1024
    : unit === 'M' ? 1048576
    : unit === 'G' ? 1073741824
    : unit === 'T' ? 1099511627776 : 1;
  return Math.round(num * mult);
}

// 关键档位（魔数校验对象）：flac/hires 为任务指定；master/atmos 本质同为 fLaC
// 容器（酷我母带/全景声实测均为 fLaC 流），一并纳入校验。
var LOSSLESS_MAGIC_TIERS = ['flac', 'flac24bit', 'hires', 'master', 'atmos'];

// 魔数白名单（§7.2）：fLaC / ID3 / RIFF / ftyp / OggS / ADTS(mp3 帧)
var MAGIC_WHITELIST = ['fLaC', 'ID3', 'RIFF', 'OggS', 'ftyp', 'ADTS'];

function asciiAt(bytes, offset, len) {
  var s = '';
  for (var i = 0; i < len; i++) {
    var b = bytes[offset + i];
    if (b === undefined || b === null) return s;
    s += String.fromCharCode(b);
  }
  return s;
}

// 识别首字节魔数：fLaC / ID3 / RIFF / OggS / ftyp(MP4, offset 4) / ADTS。
// 无法识别返回 'unknown'。
function magicOf(bytes) {
  if (!bytes || bytes.length < 2) return 'unknown';
  var head4 = asciiAt(bytes, 0, 4);
  if (head4 === 'fLaC') return 'fLaC';
  if (head4.indexOf('ID3') === 0) return 'ID3';
  if (head4 === 'RIFF') return 'RIFF';
  if (head4 === 'OggS') return 'OggS';
  if (bytes.length >= 8 && asciiAt(bytes, 4, 4) === 'ftyp') return 'ftyp';
  if (bytes[0] === 0xFF && (bytes[1] & 0xE0) === 0xE0) return 'ADTS';
  return 'unknown';
}

// 用户变量前置（§10 / B3 修订）（v0.3.0 并入）

// 与 vendor 内 userVariablesSafe 同构的读取方式：global.env.getUserVariables()
function aggUserVariables() {
  var env = typeof global !== 'undefined' && global.env ? global.env : null;
  if (env && env.getUserVariables) {
    try {
      return env.getUserVariables() || {};
    } catch (e) { /* 沙箱无 env */ }
  }
  return {};
}

// B3：QQ 源可用性前置——authst 或完整 Cookie 任一存在即视为就绪；
// 均未配置时 QQ 整体移出降级链（官方链匿名 purl 104003 必失败，不再烧预算）
function qqCredentialReady() {
  var uv = aggUserVariables();
  if (uv.qqAuthst && String(uv.qqAuthst).length >= 8) return true;
  if (uv.qqCookie && String(uv.qqCookie).length >= 8) return true;
  return false;
}

// §14 用户配置（v0.7.0 并入）
// 配置通道 = userVariables（宿主唯一插件配置存储，每次调用实时读取 = 天然热更新）。
// 插件沙箱 env 只读（无 setUserVariables API）：本模块只提供只读视图 + 校验器，
// setUserConfig 调用即抛明确错误（写入走宿主设置页）。

// 开关值语义：undefined/'' 视为开（默认全开）；'false'/'0'/'off'/'no'（不区分
// 大小写）视为关；其余一律视为开（宽容解析，防用户填 'true '/'开启' 意外关源）
function aggSwitchOf(v) {
  if (v === undefined || v === null || v === '') return true;
  var s = String(v).trim().toLowerCase();
  return !(s === 'false' || s === '0' || s === 'off' || s === 'no');
}

// userVariables 键名：enable + 源键首字母大写（enableKuwo / enableQq / ...）
function enableKeyOf(srcKey) {
  return 'enable' + srcKey.charAt(0).toUpperCase() + srcKey.slice(1);
}

// 源开关读取（全范围门控的唯一入口）：搜索聚合/透传/歌词路由/取链候选/
// 档位可用门/矩阵/doctor 均经此函数实时判定
function aggSourceEnabled(srcKey) {
  var uv = aggUserVariables();
  return aggSwitchOf(uv[enableKeyOf(srcKey)]);
}

// 档位合法性（AGG_QUALITY_ORDER 与 plugin.supportedQualities 同源）
function aggQualityValid(q) {
  return AGG_QUALITY_ORDER.indexOf(String(q)) >= 0;
}

// v1.3.0 搜索性能配置：单源预算 / 首轮页数（用户变量实时读取 = 天然热更新；非法值回退默认）
// 兼容：旧测试钩子 _aggTestOverrides.sourceBudgetMs 继续生效（优先级高于用户变量）。
function searchBudgetMsOf() {
  if (_aggTestOverrides.sourceBudgetMs != null) return _aggTestOverrides.sourceBudgetMs;
  var uv = aggUserVariables();
  var v = parseInt(uv.searchBudgetMs, 10);
  if (!(v >= 800)) v = AGG_SOURCE_BUDGET_MS;
  if (v > 8000) v = 8000;
  return v;
}
function searchMaxPagesOf() {
  var raw = _aggTestOverrides.searchMaxPages != null ? _aggTestOverrides.searchMaxPages : aggUserVariables().searchMaxPages;
  if (raw === undefined || raw === null || raw === '') return AGG_SOURCE_R1_PAGES;
  var v = parseInt(raw, 10);
  if (!(v >= 1)) v = AGG_SOURCE_R1_PAGES;
  if (v > AGG_SOURCE_PAGE_GUARD) v = AGG_SOURCE_PAGE_GUARD;
  return v;
}

// 下载默认档位：downloadQuality 配置优先，非法/未配置回退 320k
function downloadQualityOf() {
  var uv = aggUserVariables();
  var q = uv.downloadQuality;
  if (q !== undefined && q !== null && q !== '' && aggQualityValid(q)) return String(q);
  return '320k';
}

// getUserConfig 只读视图（§14）：当前生效配置 + 校验告警，供宿主/调试方读取；
// 不含任何写语义。warnings 为校验器输出（非法档位/非法源名/已关闭源的
// preferredSource 等），配置值本身不做静默纠正，只在生效处回退并告警。
function aggConfigReadView() {
  var uv = aggUserVariables();
  var warnings = [];
  var sources = {};
  for (var i = 0; i < AGG_SOURCE_ORDER.length; i++) {
    var k = AGG_SOURCE_ORDER[i];
    var ek = enableKeyOf(k);
    sources[k] = {
      label: AGG_SOURCE_LABELS[k],
      enabled: aggSourceEnabled(k),
      variableKey: ek,
      rawValue: uv[ek] !== undefined && uv[ek] !== null && uv[ek] !== '' ? String(uv[ek]) : null
    };
  }
  var dq = uv.downloadQuality;
  if (dq !== undefined && dq !== null && dq !== '' && !aggQualityValid(dq)) {
    warnings.push('downloadQuality="' + dq + '" 不是有效档位（有效：' + AGG_QUALITY_ORDER.join('/') +
      '），取链时回退 320k');
  }
  var defq = uv.defaultQuality;
  if (defq !== undefined && defq !== null && defq !== '' && !aggQualityValid(defq)) {
    warnings.push('defaultQuality="' + defq + '" 不是有效档位（有效：' + AGG_QUALITY_ORDER.join('/') + '）');
  }
  var dps = uv.downloadPreferredSource;
  var dpsValid = dps !== undefined && dps !== null && dps !== '';
  if (dpsValid && AGG_SOURCE_ORDER.indexOf(String(dps)) < 0) {
    warnings.push('downloadPreferredSource="' + dps + '" 不是有效源名（有效：' + AGG_SOURCE_ORDER.join('/') + '）');
    dpsValid = false;
  } else if (dpsValid && !aggSourceEnabled(String(dps))) {
    warnings.push('downloadPreferredSource="' + dps + '" 对应源已关闭，指定源下载不生效（回退竞速链）');
  }
  // v1.3.0：搜索性能 / 版本排序配置校验（非法值不静默纠正，生效处回退并在此告警）
  if (uv.searchBudgetMs !== undefined && uv.searchBudgetMs !== null && uv.searchBudgetMs !== '') {
    var sbm = parseInt(uv.searchBudgetMs, 10);
    if (!(sbm >= 800 && sbm <= 8000)) {
      warnings.push('searchBudgetMs="' + uv.searchBudgetMs + '" 不在有效范围 800-8000，回退默认 2800');
    }
  }
  if (uv.searchMaxPages !== undefined && uv.searchMaxPages !== null && uv.searchMaxPages !== '') {
    var smp = parseInt(uv.searchMaxPages, 10);
    if (!(smp >= 1 && smp <= 40)) {
      warnings.push('searchMaxPages="' + uv.searchMaxPages + '" 不在有效范围 1-40，回退默认 3');
    }
  }
  if (uv.versionSortWeight !== undefined && uv.versionSortWeight !== null && uv.versionSortWeight !== '') {
    var vsw = parseFloat(uv.versionSortWeight);
    if (!(vsw >= 0 && vsw <= AGG_VERSION_SORT_WEIGHT_MAX)) {
      warnings.push('versionSortWeight="' + uv.versionSortWeight + '" 不在有效范围 0-' + AGG_VERSION_SORT_WEIGHT_MAX + '，回退默认 ' + AGG_VERSION_SORT_WEIGHT_DEFAULT);
    }
  }
  return {
    version: AGG_VERSION,
    readOnly: true,
    note: '插件沙箱无配置写通道（env 只读）；请经宿主设置页修改 userVariables，实时生效。',
    variables: '定义见 plugin.userVariables（聚合层统一声明）',
    values: {
      sources: sources,
      defaultQuality: defq !== undefined && defq !== null && defq !== '' ? String(defq) : null,
      downloadQuality: downloadQualityOf() !== '320k' || (dq !== undefined && dq !== '') ? String(dq || '320k') : null,
      downloadPath: uv.downloadPath !== undefined && uv.downloadPath !== '' ? String(uv.downloadPath) : null,
      downloadPreferredSource: dpsValid ? String(dps) : null,
      allowHaitangRelay: uv.allowHaitangRelay !== undefined && uv.allowHaitangRelay !== '' ? String(uv.allowHaitangRelay) : null,
      searchBudgetMs: searchBudgetMsOf(),
      searchMaxPages: searchMaxPagesOf(),
      versionSortWeight: versionSortWeightOf()
    },
    credentials: {
      qq: { required: true, ready: qqCredentialReady(),
        hint: 'qqAuthst / qqCookie 任一长度 ≥8 即就绪；未就绪时 QQ 移出全部取链候选' },
      kugou: { required: false, configured: !!(uv.kugouCookie && String(uv.kugouCookie).length >= 8),
        hint: '匿名可取链但有风控风险；配置 kugouCookie 走 KG 备通道' },
      netease: { required: false, configured: !!(uv.neteaseCookie && String(uv.neteaseCookie).length >= 8),
        hint: 'VIP 档与部分歌需登录态' }
    },
    warnings: warnings
  };
}

// setUserConfig：无写通道，调用即抛明确错误（不做内存态兜底——热更新语义要求
// 配置跨会话生效，内存态会造成「读视图与生效值不一致」的错觉）
function aggSetUserConfigThrows() {
  throw new Error('[agg] setUserConfig 不可用：插件沙箱 env 只读，无配置写通道。' +
    '请经宿主设置页修改 userVariables（实时生效）；当前生效配置可用 getUserConfig() 读取。');
}

// §7.3 健康度追踪（HealthTracker）（v0.3.0 并入）

var HEALTH = {};
var HEALTH_FLOOR = 0.3;
var HEALTH_CEIL = 1.0;
var HEALTH_FAIL_STEP = 0.1;
var HEALTH_SUCCESS_STEP = 0.05;
var TRIP_FAIL_STREAK = 3;    // 连续 3 次失败 → 熔断 30s
var TRIP_MS = 30000;

function healthStateOf(srcKey) {
  var st = HEALTH[srcKey];
  if (!st) {
    st = { score: 1.0, failStreak: 0, openUntil: 0 };
    HEALTH[srcKey] = st;
  }
  return st;
}

function healthOf(srcKey) {
  return healthStateOf(srcKey).score;
}

// 熔断判定：openUntil 未到即熔断中；到点后半开放行，再败由 failStreak 重新熔断
function isTripped(srcKey) {
  return now() < healthStateOf(srcKey).openUntil;
}

function recordSuccess(srcKey) {
  var st = healthStateOf(srcKey);
  st.score = Math.min(HEALTH_CEIL, st.score + HEALTH_SUCCESS_STEP);
  st.failStreak = 0;
  st.openUntil = 0;
}

function recordFailure(srcKey, reason) {
  var st = healthStateOf(srcKey);
  st.score = Math.max(HEALTH_FLOOR, st.score - HEALTH_FAIL_STEP);
  st.failStreak += 1;
  if (st.failStreak >= TRIP_FAIL_STREAK) st.openUntil = now() + TRIP_MS;
  consoleWarn('[agg] health ' + srcKey + ' -0.1 -> ' + st.score.toFixed(2) +
    (reason ? ' (' + String(reason).slice(0, 80) + ')' : ''));
}

function resetHealth() {
  HEALTH = {};
}

// §7.2/B1 大小校验（SizeVerification）（v0.3.0 并入）

// 单边下限 0.88（初始值，待实机校准，范围 0.85~0.90）+ 宽松哨兵上限 1.5；
// proxyMinRatio 0.80 预留给代理通道（§7.1，v1.0 接入）
var SIZE_VERIFY = { minRatio: 0.88, proxyMinRatio: 0.80, maxRatio: 1.5 };
var PROBE_HEAD_BYTES = 4096;
var PROBE_MAX_CONTENT = 262144; // 256KB 上限：防不支持 Range 的服务器整文件下载

function parseTotalFromResp(resp) {
  var h = (resp && resp.headers) || {};
  var cr = h['content-range'] || h['Content-Range'];
  if (cr) {
    var idx = String(cr).lastIndexOf('/');
    if (idx >= 0) {
      var tail = String(cr).slice(idx + 1).trim();
      if (tail && tail !== '*') {
        var n = parseInt(tail, 10);
        if (isFinite(n) && n > 0) return n;
      }
    }
  }
  // 无 Content-Range 且整 200 时 content-length 才是总长（206 分片长度不是）
  if (resp && resp.status === 200) {
    var cl = h['content-length'] || h['Content-Length'];
    if (cl) {
      var n2 = parseInt(String(cl).replace(/[^0-9]/g, ''), 10);
      if (isFinite(n2) && n2 > 0) return n2;
    }
  }
  return null;
}

function headBytesOf(data) {
  if (!data) return null;
  try {
    if (typeof Buffer !== 'undefined' && Buffer.isBuffer && Buffer.isBuffer(data)) {
      return data;
    }
    if (typeof ArrayBuffer !== 'undefined' && data instanceof ArrayBuffer) {
      return new Uint8Array(data.slice(0, PROBE_HEAD_BYTES));
    }
    if (data.buffer instanceof ArrayBuffer) {
      var end = data.byteOffset + Math.min(data.byteLength, PROBE_HEAD_BYTES);
      return new Uint8Array(data.buffer.slice(data.byteOffset, end));
    }
  } catch (e) { return null; }
  return null;
}

// 轻量探测：单次 GET Range bytes=0-4095 同时拿 Content-Range total（实际大小）
// 与首 4KB（魔数），比 HEAD+GET 省一个 RTT。网络错误返回 { error } 由调用方
// 区分「探针故障」与「校验不通过」。
// v1.1.0 工单五：headerOnly=true 时 Range 收窄为 bytes=0-0（仅取 header 拿
// Content-Range total，不取首 4KB）——加密路魔数本就豁免，用最小负载控制
// 新增探针 RTT 的首窗延迟开销（验收口径：加密路胜出时延增量 <300ms）。
function probeMedia(url, headers, budgetMs, headerOnly) {
  if (!axios) return Promise.resolve({ error: 'no-axios' });
  var hdrs = Object.assign({}, headers || {});
  if (!hdrs.Range && !hdrs.range) {
    hdrs.Range = headerOnly ? 'bytes=0-0' : 'bytes=0-' + (PROBE_HEAD_BYTES - 1);
  }
  var timeoutMs = Math.max(200, Math.min(1200, budgetMs));
  return axios.get(url, {
    responseType: 'arraybuffer',
    timeout: timeoutMs,
    maxContentLength: PROBE_MAX_CONTENT,
    headers: hdrs
  }).then(function (resp) {
    return {
      status: resp && resp.status,
      total: parseTotalFromResp(resp),
      headBytes: headBytesOf(resp && resp.data)
    };
  }, function (e) {
    return { error: errMsg(e) };
  });
}

function nominalSizeOf(raw, quality) {
  var qv = raw && raw.qualities ? raw.qualities[quality] : null;
  return qv ? parseSizeToBytes(qv.size) : null;
}

var NOMINAL_CACHE = {};
var NOMINAL_TTL = 600000;

// 标称大小兜底：raw.qualities 缺失时调 provider.getMusicInfo（1s 预算，TTL 10min 缓存）；
// 仍拿不到返回 null（跳过比值校验，魔数校验照做）
async function fetchNominalSize(cand, ctx) {
  var synced = nominalSizeOf(cand.raw, ctx.quality);
  if (synced !== null && synced !== undefined) return synced;
  var provider = __AGG_PROVIDERS[cand.srcKey];
  if (!provider || typeof provider.getMusicInfo !== 'function') return null;
  var cacheKey = cand.srcKey + ':' + String(cand.raw.id) + ':' + ctx.quality;
  var hit = NOMINAL_CACHE[cacheKey];
  if (hit && now() - hit.t < NOMINAL_TTL) return hit.v;
  var remaining = ctx.deadline - now();
  if (remaining <= 300) return null;
  try {
    var info = await withTimeout(
      provider.getMusicInfo(shallowCopy(cand.raw)),
      Math.min(1000, remaining),
      'nominal ' + cand.srcKey
    );
    var size = (info && info.qualities && info.qualities[ctx.quality])
      ? parseSizeToBytes(info.qualities[ctx.quality].size) : null;
    NOMINAL_CACHE[cacheKey] = { t: now(), v: size };
    return size;
  } catch (e) {
    return null;
  }
}

/**
 * 单路结果校验（§7.4 + B1 修订）。返回 { ok, reason?, unverified?, encrypted? }。
 * 分支顺序：
 *   1. 无 url → 不通过；
 *   2. 加密档（ekey ≥16B / cek / .mflac|.mgg URL）→ 魔数豁免（容器非裸流），
 *      ekey 长度合法性校验保留；v1.1.0 工单五起增加大小单边下限校验
 *      （probeMedia headerOnly 取 Content-Range total，minRatio 0.88 同明文路），
 *      探针网络错误仍按"放行 + _unverified"处理；
 *   3. 探针（Range GET）→ 网络错误 ≠ 校验失败：放行 + _unverified 标记
 *      （防误杀真机可播链路——数据中心 IP 与真机网络差异大）；
 *   4. 关键档位魔数：不在白名单 → 虚标作废；
 *   5. 大小比值：total 与标称双方都可得时，越 [0.88, 1.5] 界 → 作废。
 */
async function verifyLaneResult(res, quality, nominal, ctx) {
  if (!res || typeof res !== 'object' || !res.url) {
    return { ok: false, reason: 'no-url' };
  }
  var hasEkey = typeof res.ekey === 'string' && res.ekey.length >= 16;
  var hasCek = res.cek !== undefined && res.cek !== null && res.cek !== '';
  var encUrl = /\.(mflac|mgg)(\?|#|$)/.test(String(res.url));
  if (typeof res.ekey === 'string' && res.ekey.length < 16) {
    // ekey 存在但不合法 → 该路结果残缺，作废让位下一路（不进探针：密文无裸流语义）
    return { ok: false, reason: 'ekey-too-short' };
  }
  if (hasEkey || hasCek || encUrl) {
    // v1.1.0 工单五：加密路不再直接放行——保留大小单边下限校验，仅豁免魔数
    // （密文容器非裸流，魔数白名单不适用；但 QQ 30s 试听片段等"合法密文 + 短内容"
    // 仍须被 size-low 拒绝，否则高品档竞速会被试听链路占坑）。
    // 流程：预算守卫 → probeMedia(headerOnly) 取 Content-Range total → 与标称
    // 单边下限比对（minRatio 0.88 同明文路）；探针网络错误沿用"放行 + _unverified"
    // 语义（与明文路一致，不因网络差异误杀真机可播链路）。
    var remainingE = ctx.deadline - now();
    if (remainingE <= 200) {
      return { ok: false, reason: 'budget-exhausted' };
    }
    var probeE = await probeMedia(res.url, res.headers, remainingE, true);
    if (probeE.error) {
      try { res._unverified = probeE.error; } catch (e0) { /* 冻结对象忽略 */ }
      // v1.2.0：探针故障分支保留 encrypted 标记（对齐 v0.9.2 P1-2 语义）——
      // 胜出结果的 out.encrypted 由 verdict.encrypted 派生，加密路放行时不得丢标记
      return { ok: true, encrypted: true, unverified: true };
    }
    if (probeE.total !== null && nominal !== null && nominal !== undefined) {
      var lowE = nominal * SIZE_VERIFY.minRatio;
      if (probeE.total < lowE) {
        return { ok: false, reason: 'size-low(' + probeE.total + '<' + Math.round(lowE) + ')' };
      }
    }
    return { ok: true, encrypted: true };
  }
  var remaining = ctx.deadline - now();
  if (remaining <= 200) {
    return { ok: false, reason: 'budget-exhausted' };
  }
  var probe = await probeMedia(res.url, res.headers, remaining);
  if (probe.error) {
    try { res._unverified = probe.error; } catch (e) { /* 冻结对象忽略 */ }
    return { ok: true, unverified: true };
  }
  if (LOSSLESS_MAGIC_TIERS.indexOf(quality) >= 0 && probe.headBytes && probe.headBytes.length >= 4) {
    var mg = magicOf(probe.headBytes);
    if (MAGIC_WHITELIST.indexOf(mg) < 0) {
      return { ok: false, reason: 'magic:' + mg };
    }
  }
  if (probe.total !== null && nominal !== null && nominal !== undefined) {
    var low = nominal * SIZE_VERIFY.minRatio;
    var high = nominal * SIZE_VERIFY.maxRatio;
    if (probe.total < low) {
      return { ok: false, reason: 'size-low(' + probe.total + '<' + Math.round(low) + ')' };
    }
    if (probe.total > high) {
      return { ok: false, reason: 'size-high(' + probe.total + '>' + Math.round(high) + ')' };
    }
  }
  return { ok: true };
}

// §7 取链调度器（FetchScheduler）（v0.3.0 并入）

// 8s 预算分配（§7.4/A3 修订）：首轮窗口 ≤4s（K=3/单路 1.5s/grace 300ms），
// 降级窗口 ≤2s（K=2/单路 1.2s/grace 0）；大小校验计入窗口；总闸 8s 优先级最高。
// 对象可变（非冻结）：测试经 _test 钩子覆盖预算后须自行还原。
var FETCH_BUDGET = {
  TOTAL_MS: 8000,
  FIRST: { windowMs: 4000, K: 3, laneTimeoutMs: 1500, graceMs: 300 },
  FALLBACK: { windowMs: 2000, K: 2, laneTimeoutMs: 1200, graceMs: 0 }
};

// 真 AbortController + 兜底 stub（老 Hermes 无 AbortController 时仅做标记，
// 不向 provider 传 signal）
function makeAbort() {
  if (typeof AbortController === 'function') {
    try {
      var c = new AbortController();
      return {
        real: true,
        signal: c.signal,
        abort: function () { try { c.abort(); } catch (e) { /* 已 abort */ } }
      };
    } catch (e) { /* fallthrough */ }
  }
  var aborted = false;
  var listeners = [];
  return {
    real: false,
    signal: null,
    abort: function () {
      if (aborted) return;
      aborted = true;
      for (var i = 0; i < listeners.length; i++) {
        try { listeners[i](); } catch (e) { /* 忽略监听器异常 */ }
      }
    },
    onAbort: function (fn) { if (aborted) fn(); else listeners.push(fn); }
  };
}

// 同源多通道注册表（§7.1）：lane = (源 × 通道)。各源默认单通道
// 'provider'（= provider.getMediaSource 整链，其内部已自带多通道接力/竞速：
// 酷狗 3 路并行、酷我 DES 双通道+海棠、咪咕 4 通道、QQ 官方→海棠→听会→vkeys→s01s）；
// 代理通道等经 registerChannel 扩展，调度器/校验/预算对各通道一致生效。
var AGG_CHANNELS = {};

var PROVIDER_CHANNEL = {
  name: 'provider',
  // signal 预留：vendor 不消费 abort 信号，胜出后其底层请求自行结束、结果被丢弃
  invoke: function (cctx) {
    var provider = __AGG_PROVIDERS[cctx.srcKey];
    if (!provider || typeof provider.getMediaSource !== 'function') {
      return Promise.reject(new Error('[agg] 源 ' + cctx.srcKey + ' 不支持 getMediaSource'));
    }
    return Promise.resolve(provider.getMediaSource(shallowCopy(cctx.raw), cctx.quality));
  }
};

function registerChannel(srcKey, channel) {
  if (!channel || !channel.name || typeof channel.invoke !== 'function') {
    throw new Error('[agg] registerChannel: channel 需含 name 与 invoke');
  }
  if (!AGG_CHANNELS[srcKey]) AGG_CHANNELS[srcKey] = [];
  AGG_CHANNELS[srcKey].push(channel);
  return function () { unregisterChannel(srcKey, channel.name); };
}

function unregisterChannel(srcKey, name) {
  var list = AGG_CHANNELS[srcKey];
  if (!list) return;
  var next = [];
  for (var i = 0; i < list.length; i++) {
    if (list[i].name !== name) next.push(list[i]);
  }
  AGG_CHANNELS[srcKey] = next;
}

function channelsOf(srcKey) {
  var list = AGG_CHANNELS[srcKey];
  return (list && list.length) ? list : [PROVIDER_CHANNEL];
}

/**
 * 候选构建（§7.4）：候选源集合取 _qualitySources[quality]（§8 逐档路由）；
 * 声明表整体缺失时按 SOURCE_HOST_QUALITIES 矩阵门兜底（防御路径），声明表
 * 存在但该档未声明 → 零候选（§8.2 交还宿主逐档循环）；QQ 未配置凭据整体
 * 剔除（B3）；每源展开为 (源 × 通道) 候选；rank = 固定位次 + (1-健康度)×0.1
 * （§7.3 ±10% 微调，不跨位次重排——口径③固定顺序为主，健康度仅扰动
 * 同预算窗口内的并行优先级）。
 */
function buildCandidates(musicItem, quality) {
  var srcMap = (musicItem && musicItem._src) || {};
  var qsrcMap = (musicItem && musicItem._qualitySources) || null;
  var preferred = qsrcMap ? (qsrcMap[quality] || null) : null;
  var keys = [];
  var i, k;
  if (Array.isArray(preferred) && preferred.length) {
    for (i = 0; i < AGG_SOURCE_ORDER.length; i++) {
      k = AGG_SOURCE_ORDER[i];
      if (preferred.indexOf(k) >= 0 && srcMap[k]) keys.push(k);
    }
  } else if (!qsrcMap) {
    // 矩阵门兜底仅用于声明表整体缺失的防御路径（手工构造条目等）；
    // 声明表存在但该档未声明 → 零候选（§8.2/§8.3：只声明实际可得档位，
    // 未声明档位返回 null 交还宿主逐档循环，不烧预算强取）
    for (i = 0; i < AGG_SOURCE_ORDER.length; i++) {
      k = AGG_SOURCE_ORDER[i];
      if (srcMap[k] && SOURCE_HOST_QUALITIES[k] && SOURCE_HOST_QUALITIES[k].indexOf(quality) >= 0) {
        keys.push(k);
      }
    }
  }
  var gated = [];
  for (var g = 0; g < keys.length; g++) {
    k = keys[g];
    if (!aggSourceEnabled(k)) continue; // §14：源开关关闭 → 移出取链候选
    if (k === 'qq' && !qqCredentialReady()) continue;
    gated.push(k);
  }
  var cands = [];
  for (var c = 0; c < gated.length; c++) {
    var srcKey = gated[c];
    var channels = channelsOf(srcKey);
    for (var ch = 0; ch < channels.length; ch++) {
      cands.push({
        srcKey: srcKey,
        raw: srcMap[srcKey],
        channel: channels[ch],
        qualityParam: qualityParamOf(srcKey, quality),
        fixedIndex: c,
        rank: c + (1 - healthOf(srcKey)) * 0.1
      });
    }
  }
  cands.sort(function (a, b) { return a.rank - b.rank; });
  return cands;
}

// 候选分窗：首窗 K=3，其后每窗 K=2（§7.4 滑动窗口）
function chunkWindows(cands) {
  var chunks = [];
  var i = 0;
  var first = true;
  while (i < cands.length) {
    var k = first ? FETCH_BUDGET.FIRST.K : FETCH_BUDGET.FALLBACK.K;
    chunks.push(cands.slice(i, i + k));
    i += k;
    first = false;
  }
  return chunks;
}

/**
 * 单路执行：通道调用 → 单路超时 → 大小/魔数校验 → 记账。
 * 记账语义（§7.3）：显式超时与校验失败 = 失败扣分；因胜出/窗口截止/总闸被
 * abort 的在飞请求不计失败；熔断中的候选直接跳过（不计失败）。
 * 胜出后 ctx.abortAll('won') 统一 abort 其余在飞路。
 */
async function runLane(cand, ctx, cfg, entry) {
  var srcKey = cand.srcKey;
  var timer = null;
  try {
    var ac = makeAbort();
    entry.ac = ac;
    var laneDeadline = Math.min(cfg.laneTimeoutMs, Math.max(1, ctx.deadline - now()));
    var invokeP;
    try {
      invokeP = Promise.resolve(cand.channel.invoke({
        srcKey: srcKey,
        raw: shallowCopy(cand.raw),
        quality: cand.qualityParam,
        hostQuality: ctx.quality,
        signal: ac.real ? ac.signal : null
      }));
    } catch (eSync) {
      invokeP = Promise.reject(eSync);
    }
    var timeoutP = new Promise(function (resolve, reject) {
      timer = setTimeout(function () {
        entry.reason = 'timeout';
        try { ac.abort(); } catch (e) { /* 已 abort */ }
        reject(new Error('[agg] lane timeout ' + srcKey + '/' + cand.channel.name + ' ' + laneDeadline + 'ms'));
      }, laneDeadline);
    });
    var res = await Promise.race([invokeP, timeoutP]);
    if (timer) { clearTimeout(timer); timer = null; }
    entry.settled = true;
    if (ctx.won) return { ok: false, aborted: true };
    var nominal = await fetchNominalSize(cand, ctx);
    var verdict = await verifyLaneResult(res, ctx.quality, nominal, ctx);
    if (verdict.ok) {
      recordSuccess(srcKey);
      var out = {
        ok: true,
        result: res,
        srcKey: srcKey,
        channel: cand.channel.name,
        verified: !verdict.unverified,
        encrypted: !!verdict.encrypted
      };
      if (!ctx.won) {
        ctx.won = out;
        ctx.abortAll('won');
      }
      return out;
    }
    recordFailure(srcKey, 'verify ' + verdict.reason);
    return { ok: false, reason: verdict.reason };
  } catch (e) {
    if (timer) clearTimeout(timer);
    entry.settled = true;
    if (entry.reason === 'timeout') {
      recordFailure(srcKey, 'timeout');
      return { ok: false, reason: 'timeout' };
    }
    // 胜出/窗口截止/总闸触发的 abort：不计失败（§7.3）
    if (entry.reason === 'won' || entry.reason === 'window' || entry.reason === 'total') {
      return { ok: false, aborted: true };
    }
    recordFailure(srcKey, errMsg(e));
    return { ok: false, reason: errMsg(e) };
  }
}

/**
 * 滑动窗口：并发拉起窗口内全部候选（chunk 长度即 K），任一路胜出即结束；
 * 全部落定且无胜出提前结束（不空烧窗口预算）；窗口截止（+grace）统一 abort
 * 在飞路后结束。窗口时长 = min(cfg.windowMs, 剩余总预算)。
 */
function runWindow(chunk, cfg, ctx) {
  return new Promise(function (resolve) {
    var finished = false;
    var launched = 0;
    var settled = 0;
    var entries = [];
    var backstop = null;
    function finish() {
      if (finished) return;
      finished = true;
      if (backstop) clearTimeout(backstop);
      for (var i = 0; i < entries.length; i++) {
        var en = entries[i];
        if (!en.settled) {
          if (!en.reason) en.reason = 'window';
          if (en.ac) { try { en.ac.abort(); } catch (e) { /* 已 abort */ } }
        }
      }
      resolve(ctx.won || null);
    }
    if (!chunk.length || ctx.won) {
      resolve(ctx.won || null);
      return;
    }
    var windowMs = Math.min(cfg.windowMs, Math.max(0, ctx.deadline - now()));
    var skipped = 0;
    for (var i2 = 0; i2 < chunk.length; i2++) {
      (function (cand) {
        if (isTripped(cand.srcKey)) {
          // 熔断跳过不计入 launched；全部候选落定（跳过数+已落定数）才允许结束窗口
          skipped += 1;
          if (skipped + settled >= chunk.length) finish();
          return;
        }
        launched += 1;
        var entry = { settled: false, reason: null, ac: null };
        entries.push(entry);
        ctx.inflight.push(entry);
        runLane(cand, ctx, cfg, entry).then(function () {
          entry.settled = true;
          settled += 1;
          // settled 仅计已发射路（跳过走 skipped）；全部已发射路落定即结束
          if (ctx.won || settled >= launched) finish();
        });
      })(chunk[i2]);
    }
    if (launched === 0) {
      finish();
      return;
    }
    backstop = setTimeout(finish, windowMs + cfg.graceMs);
  });
}

/**
 * 调度总入口（§7）：8s 总闸（优先级最高，到点 abort 全部在飞）→ 按分窗依序
 * 竞速 → 胜出即返回；无候选返回 null（§8.2 交还宿主逐档循环）；全部失败
 * 返回 undefined（调用方抛错）。窗口间也遵守总预算，逐窗扣除。
 */
async function scheduleFetch(musicItem, quality) {
  var ctx = {
    quality: quality,
    deadline: now() + FETCH_BUDGET.TOTAL_MS,
    inflight: [],
    won: null,
    abortAll: function (reason) {
      for (var i = 0; i < ctx.inflight.length; i++) {
        var en = ctx.inflight[i];
        if (!en.settled) {
          if (!en.reason) en.reason = reason;
          if (en.ac) { try { en.ac.abort(); } catch (e) { /* 已 abort */ } }
        }
      }
    }
  };
  var cands = buildCandidates(musicItem, quality);
  if (!cands.length) return null;
  var chunks = chunkWindows(cands);
  var watchdog = setTimeout(function () { ctx.abortAll('total'); }, FETCH_BUDGET.TOTAL_MS);
  try {
    for (var w = 0; w < chunks.length; w++) {
      if (ctx.won) break;
      if (ctx.deadline - now() <= 100) break;
      var cfg = w === 0 ? FETCH_BUDGET.FIRST : FETCH_BUDGET.FALLBACK;
      await runWindow(chunks[w], cfg, ctx);
    }
  } finally {
    clearTimeout(watchdog);
    ctx.abortAll('total'); // 收尾：任何残留请求统一 abort
  }
  // 候选非空且未胜出 = 全败 → 返回 undefined（区别于无候选 null），调用方据此抛错
  return ctx.won || undefined;
}

// [v1.3.2 F5] 音质标识兜底：宿主 badge 映射（HR/SQ+/SQ/HQ/LQ）只认 128k~hires 六档；
// 榜单/歌单详情等 vendor 条目常无 qualities 元数据 → 交集门后 qMap 为空 → 聚合结果
// 无任何音质标识。此时按源真实支持的最低档补 128k（SOURCE_HOST_QUALITIES 六源矩阵
// 均含 128k，非虚标）；路由表侧对该批无任何元数据的源按 SOURCE_HOST_QUALITIES 全矩阵
// 补齐逐档路由——与 v0.8.0「无声明表走矩阵兜底」的取链面完全一致，避免只补 128k
// 一档让声明表出现后其余档位被「表在档未声明即不可用」语义挡死。
var QUALITY_BADGE_KEYS = ['hires', 'flac24bit', 'flac', '320k', '192k', '128k'];

function ensureMinQualityBadge(qMap, qSrc, srcKeys) {
  var hasBadge = false;
  var i;
  for (i = 0; i < QUALITY_BADGE_KEYS.length; i++) {
    if (qMap[QUALITY_BADGE_KEYS[i]]) { hasBadge = true; break; }
  }
  if (hasBadge) return;
  // 补最低档 128k（显示面）：六源矩阵均含 128k，真实可取
  if (!qMap['128k']) qMap['128k'] = { size: null, bitrate: null, format: null };
  for (i = 0; i < srcKeys.length; i++) {
    var sk = srcKeys[i];
    if (!sk) continue;
    var srcHadMeta = false;
    for (var qk in qSrc) {
      if (Object.prototype.hasOwnProperty.call(qSrc, qk) && qSrc[qk] && qSrc[qk].indexOf(sk) >= 0) {
        srcHadMeta = true;
        break;
      }
    }
    // 128k 恒入路由表（该源真实支持）
    var l128 = qSrc['128k'] || (qSrc['128k'] = []);
    if (l128.indexOf(sk) < 0) l128.push(sk);
    // 该源无任何真实元数据：全矩阵补路由（取链面 ≡ v0.8.0 矩阵兜底防御路径）
    if (!srcHadMeta) {
      var matrix = SOURCE_HOST_QUALITIES[sk] || [];
      for (var m = 0; m < matrix.length; m++) {
        var lm = qSrc[matrix[m]] || (qSrc[matrix[m]] = []);
        if (lm.indexOf(sk) < 0) lm.push(sk);
      }
    }
  }
}

// 档位可用性门（§8.2）：以条目 _qualitySources 声明表为准（声明表存在但该档
// 未声明 → 不可用，返回 null 交还宿主逐档循环）；声明表整体缺失时按
// SOURCE_HOST_QUALITIES 矩阵兜底（防御路径），与 buildCandidates 口径一致
function aggQualityAvailable(musicItem, quality) {
  var srcMap = (musicItem && musicItem._src) || {};
  var qsrcMap = (musicItem && musicItem._qualitySources) || null;
  var preferred = qsrcMap ? (qsrcMap[quality] || null) : null;
  var i, k;
  if (Array.isArray(preferred) && preferred.length) {
    for (i = 0; i < preferred.length; i++) {
      k = preferred[i];
      if (srcMap[k] && aggSourceEnabled(k) && !(k === 'qq' && !qqCredentialReady())) return true;
    }
    // 声明表存在且该档有声明 → 以声明表为准（即使逐源全被门控剔除，
    // 也走 buildCandidates → 零候选 → null 的统一口径，不再矩阵兜底）
    return false;
  }
  if (qsrcMap) return false; // 声明表存在但该档未声明 → 不可用（§8.2 交还宿主）
  for (i = 0; i < AGG_SOURCE_ORDER.length; i++) {
    k = AGG_SOURCE_ORDER[i];
    if (srcMap[k] && SOURCE_HOST_QUALITIES[k] && SOURCE_HOST_QUALITIES[k].indexOf(quality) >= 0 &&
        aggSourceEnabled(k) && !(k === 'qq' && !qqCredentialReady())) {
      return true;
    }
  }
  return false;
}

// FinalItem 构建（§4.2）

// 稳定 id（§5.2 A2 修订）：锚定默认源 的 平台:trackId，SHA-1 十六进制；variant 集合变化不影响 id。
function stableIdOf(srcKey, raw) {
  return 'agg' + sha1Hex(srcKey + ':' + String(raw.id));
}

/**
 * 单源原始条目 → FinalItem（v0.1.0 骨架版：不做跨源合并，单源快照即全集）
 * qualities/_qualitySources 留空——精确档位与逐档路由在实施第 5 步补齐。
 * _default 取条目来源源（合并步骤起按 §4.2 主 variant 选取，kuwo 优先）。
 *
 * 骨架版已知取舍（交叉质检 P3-5）：search 对 sheet/lyric 类型同样走本函数，
 * 仅映射 title/artist/album 等音乐向展示字段——ISheetItem 特有展示字段
 * （如 worksCount）不出现在 FinalItem 顶层，仅保留在 _src 快照内（getMusicSheetInfo
 * 路由回源不受影响）；后续步骤如宿主歌单卡片展示缺字段，再按 type 分支透传。
 */
function buildFinalItem(srcKey, raw, sessionId) {
  if (!raw || typeof raw !== 'object') return null;
  if (raw.id === undefined || raw.id === null || raw.id === '') return null;
  // §4.2：_src 为按源键控的只读快照 map（{ kuwo: {...}, qq: {...} }），
  // v0.1.0 单源透传阶段每个 FinalItem 只有一个源键（合并步骤起多源填充）
  var srcMap = {};
  srcMap[srcKey] = freezeSnapshot(raw);
  // §8.3 动态 qualities/_qualitySources（v0.5.0 接入调度器）：raw.qualities ×
  // SOURCE_HOST_QUALITIES[srcKey] 交集门，只声明该源声明过的档位（不虚标）；
  // 每档记录 size（经 parseSizeToBytes 归一为字节；无法解析记 null）与
  // bitrate/format；_qualitySources 逐档记录来源源（getMediaSource 调度器
  // 取候选的依据，跨源合并后按 §4.2 多源填充）。
  var hostQs = SOURCE_HOST_QUALITIES[srcKey] || [];
  var rawQ = (raw.qualities && typeof raw.qualities === 'object') ? raw.qualities : {};
  var qMap = {};
  var qSrc = {};
  for (var qi = 0; qi < hostQs.length; qi++) {
    var qk = hostQs[qi];
    var qv = rawQ[qk];
    if (!qv || typeof qv !== 'object') continue;
    qMap[qk] = {
      size: parseSizeToBytes(qv.size),
      bitrate: qv.bitrate !== undefined ? qv.bitrate : null,
      format: qv.format !== undefined ? qv.format : null
    };
    var srcList = qSrc[qk] || (qSrc[qk] = []);
    srcList.push(srcKey);
  }
  // S3（v0.4.1 并入）：白名单外字段透传（singerList/albumid/artistId 等宿主跳转
  // 字段），固定键与 '_' 内部键不受影响。
  // v0.8.0 补丁（同 buildMergedFinalItem）：源无 qualities 元数据时不挂空声明表，
  // 让 aggQualityAvailable 走矩阵兜底防御路径（榜单/歌单详情 vendor 条目常缺元数据）。
  var hasQDecl = false;
  for (var qk0 in qSrc) { if (qSrc[qk0] && qSrc[qk0].length) { hasQDecl = true; break; } }
  // [v1.3.2 F5] 音质标识兜底（同 buildMergedFinalItem）：无 badge 档位时补最低档
  // 128k 显示档 + 该源全矩阵路由表（取链面 ≡ 矩阵兜底）。调用后声明表必非空。
  ensureMinQualityBadge(qMap, qSrc, [srcKey]);
  hasQDecl = true;
  var fi = {
    id: stableIdOf(srcKey, raw),
    title: raw.title,
    artist: raw.artist,
    album: raw.album,
    duration: raw.duration,
    coverImg: raw.coverImg !== undefined ? raw.coverImg : raw.cover,
    platform: 'agg',
    primaryKey: ['id'],
    qualities: qMap,       // §8.3：该源实有档位（size 归一字节，缺解析记 null）
    _src: srcMap,
    _srcOrder: AGG_SOURCE_ORDER,
    _default: srcKey,
    _variants: [],        // 单源透传：无跨源变体（music 聚合走 buildMergedFinalItem）
    _session: sessionId || null
  };
  if (hasQDecl) fi._qualitySources = qSrc; // §8.3：逐档来源路由表（口径③顺序）
  // v1.0.0 D1：MV 标识聚合（点灯关键）——显式聚合优先于透传
  return applyMvAggregation(passThroughExtras(fi, raw));
}

// §MV MV 聚合（v1.0.0 并入，方案 D1/D2/D4/D5）

// MV 标识字段键（宿主 canPlayMusicVideo 认 9 种键名，此处收录五源实际产出的 7 种；
// 汽水无 MV 能力、不产出任何标识，天然出局）
// [v1.3.1-r2] 补 is_video/bvid：宿主 canPlayMusicVideo 九字段名单（Toskysun/MusicFree
//   v1.0.0 src/utils/musicVideo.ts）全量对齐；当前六源 vendor 均不产出这两键，
//   补齐后即便 vendor 未来携带（如 B 站类视频源）也能正确聚合/清理
var AGG_MV_ID_KEYS = ['mv', 'mvId', 'mvid', 'mvHash', 'mvVid', 'mvCopyrightId', 'videoId', 'is_video', 'bvid'];

// 单源 MV 取链超时（MV 取链比音频慢，各源 provider 内部已含多通道竞速）
var AGG_MV_RESOLVE_MS = 2500;

// [v1.3.2 F4] MV 画质全档声明（与 manifest supportedVideoQualities 同源引用）：
// 五源档位并集 6 档，结构化形态对齐宿主 IVideoQualityOption。mergeMvAvailableQualities
// 以此为准，把每个成功的 getMvSource 结果的 availableVideoQualities 补成全档——
// 宿主画质菜单无论按 manifest 声明还是按 result.availableVideoQualities 合并，
// 都能见全部可切换档位（单档结果的根因兜底）。
var AGG_MV_QUALITY_OPTS = [
  { key: '240p', label: '240P', width: 426, height: 240, mimeType: 'video/mp4' },
  { key: '360p', label: '360P', width: 640, height: 360, mimeType: 'video/mp4' },
  { key: '480p', label: '480P', width: 854, height: 480, mimeType: 'video/mp4' },
  { key: '720p', label: '720P', width: 1280, height: 720, mimeType: 'video/mp4' },
  { key: '1080p', label: '1080P', width: 1920, height: 1080, mimeType: 'video/mp4' },
  { key: '4k', label: '4K', width: 3840, height: 2160, mimeType: 'video/mp4' }
];

// [v1.3.2 F4] 把 manifest 全档并入 MV 结果的 availableVideoQualities：
//   - vendor 实测档位（含 width/height/bitrate 等真实元数据）保留且置前；
//   - manifest 中 vendor 未返回的档位按结构化声明补齐在尾部；
//   - 已有档位按 key 去重。返回 out 便于调用方链式收口。
// 只补「可切换档位清单」字段，url/videoQuality 等取链结果一字不动。
function mergeMvAvailableQualities(out) {
  if (!out || typeof out !== 'object') return out;
  var have = {};
  var merged = [];
  var exist = out.availableVideoQualities;
  if (Array.isArray(exist)) {
    for (var i = 0; i < exist.length; i++) {
      var e = exist[i];
      var ek = e && typeof e === 'object' ? e.key : e;
      if (ek === undefined || ek === null || have[ek]) continue;
      have[ek] = true;
      merged.push(e);
    }
  }
  for (var j = 0; j < AGG_MV_QUALITY_OPTS.length; j++) {
    var opt = AGG_MV_QUALITY_OPTS[j];
    if (!have[opt.key]) merged.push(shallowCopy(opt));
  }
  out.availableVideoQualities = merged;
  return out;
}

// 收集单个 raw 的 MV 标识字段（严格 truthy：空字符串 / 0 / null / undefined 不算有标识）
function mvIdsOf(raw) {
  var ids = {};
  if (!raw || typeof raw !== 'object') return ids;
  for (var i = 0; i < AGG_MV_ID_KEYS.length; i++) {
    var k = AGG_MV_ID_KEYS[i];
    var v = raw[k];
    // [v1.3.1-r2] 补排除 false：is_video 等布尔标记的 false 值不是 MV 标识
  // （原注释自述「严格 truthy」但漏了 false，is_video:false 会被误挂 _mvSources）
  if (v !== undefined && v !== null && v !== '' && v !== 0 && v !== false && typeof v !== 'function') {
      ids[k] = v;
    }
  }
  return ids;
}

// D1：按源序扫描源快照表 → { mv, sources }。
//   mv = 首个有标识源的标识值（键序按 AGG_MV_ID_KEYS 取首个真值；宿主门槛只要求
//   truthy，取真值兼顾 getVideoIdentifier 消费）；
//   sources = [{ srcKey, ids: {...该源全部 MV 字段} }]，按口径③固定源序，只收录
//   带标识的源（汽水天然出局）。
function aggregateMvSources(srcMap, order) {
  var sources = [];
  if (!srcMap || typeof srcMap !== 'object') return { mv: null, sources: sources };
  var ord = (Array.isArray(order) && order.length) ? order : AGG_SOURCE_ORDER;
  var mv = null;
  for (var i = 0; i < ord.length; i++) {
    var k = ord[i];
    var ids = mvIdsOf(srcMap[k]);
    var hit = null;
    for (var j = 0; j < AGG_MV_ID_KEYS.length; j++) {
      if (AGG_MV_ID_KEYS[j] in ids) { hit = ids[AGG_MV_ID_KEYS[j]]; break; }
    }
    if (hit === null) continue;
    if (mv === null) mv = hit;
    sources.push({ srcKey: k, ids: ids });
  }
  return { mv: mv, sources: sources };
}

// D1 落点：buildFinalItem / buildMergedFinalItem 在 passThroughExtras 之后调用。
// 任一参与源带标识 → 顶层挂 mv + _mvSources；无任何源带标识 → 清除透传带入的
// falsy MV 键（空串/0 不挂，防「标识聚合误挂到无 MV 条目」——方案 §四回归防护）。
function applyMvAggregation(fi) {
  if (!fi || typeof fi !== 'object' || !fi._src || typeof fi._src !== 'object') return fi;
  var agg = aggregateMvSources(fi._src, fi._srcOrder);
  if (agg.sources.length) {
    fi.mv = agg.mv;
    fi._mvSources = agg.sources;
  } else {
    for (var i = 0; i < AGG_MV_ID_KEYS.length; i++) {
      var k = AGG_MV_ID_KEYS[i];
      if (k in fi && !fi[k]) delete fi[k];
    }
  }
  return fi;
}

// D2 第 1 步 / D5 现场扫描兜底：MV 路由表——顶层 _mvSources 优先，缺失时按 _src
// 现场扫描（收藏/歌单里的存量 agg 条目顶层无 mv 字段，只要快照有标识就能播）。
function mvSourceRoutes(musicItem) {
  if (!musicItem || typeof musicItem !== 'object') return [];
  if (Array.isArray(musicItem._mvSources) && musicItem._mvSources.length) {
    return musicItem._mvSources;
  }
  return aggregateMvSources(musicItem._src, musicItem._srcOrder).sources;
}

// [v1.3.0 D6] fallback 路由键序：内部字段丢失（路由表为空）但顶层仍带 MV 标识时，
// 按标识归属构造候选源序。kuwo/migu/kugou 有严格 title+artist 搜索通道 → 无条件
// 参与；qq 仅在顶层 videoId/mvVid（vid 空间，归属明确）时参与；netease 无严格
// 搜索通道（数字 id 歌曲与 MV 空间分离，误配会取错 MV）、qishui 无 MV → 均排除。
function mvFallbackRouteKeys(musicItem) {
  var ids = mvIdsOf(musicItem);
  var keys = [];
  if (!Object.keys(ids).length) return keys;
  keys.push('kuwo', 'migu', 'kugou');
  if (ids.videoId || ids.mvVid) keys.push('qq');
  return keys;
}

// [v1.3.0 D6] fallback 模式下的 provider 输入：以顶层基础字段 + 源归属标识构造
// 最小条目（platform 置为目标源，provider 内部搜索通道按 platform 识别自家条目）。
// 只携带该源自家命名空间的 id（mvHash/vid/mvSongId/mvCopyrightId），顶层跨源
// 复合 id 一律不透传——配合 noDirectId 防跨源 id 互串取错 MV。
function buildMvFallbackInput(srcKey, musicItem) {
  var input = {
    id: musicItem.id, title: musicItem.title, artist: musicItem.artist,
    album: musicItem.album, duration: musicItem.duration,
    coverImg: musicItem.coverImg !== undefined ? musicItem.coverImg : musicItem.cover,
    platform: srcKey
  };
  if (srcKey === 'kugou') {
    if (musicItem.mvHash) input.mvHash = musicItem.mvHash;
  } else if (srcKey === 'qq') {
    var vid = musicItem.videoId || musicItem.mvVid;
    if (vid) { input.vid = String(vid); input.mid = musicItem.songmid || undefined; }
  } else if (srcKey === 'kuwo') {
    if (musicItem.mvSongId) input.mvSongId = musicItem.mvSongId;
  } else if (srcKey === 'migu') {
    if (musicItem.mvCopyrightId) input.mvCopyrightId = musicItem.mvCopyrightId;
  }
  return input;
}

// 路由

/**
 * 解析条目 → { key, raw }：
 *  - FinalItem（platform==='agg'）：_default 优先，缺失时按 _srcOrder 顺序取第一个
 *    非空 _src 快照（容错：default 源快照缺失仍可路由，不会死链）；
 *  - 非 agg 条目（防御性透传，如宿主从单源插件流转发来的条目）：按 platform 直配。
 * 找不到可路由源返回 null。
 */
function resolveAggRoute(musicItem) {
  if (!musicItem || typeof musicItem !== 'object') return null;
  if (musicItem.platform === 'agg') {
    var order = [];
    if (musicItem._default) order.push(musicItem._default);
    var srcOrder = Array.isArray(musicItem._srcOrder) && musicItem._srcOrder.length
      ? musicItem._srcOrder : AGG_SOURCE_ORDER;
    for (var i = 0; i < srcOrder.length; i++) {
      if (order.indexOf(srcOrder[i]) < 0) order.push(srcOrder[i]);
    }
    var srcMap = musicItem._src || {};
    for (var j = 0; j < order.length; j++) {
      if (srcMap[order[j]]) return { key: order[j], raw: srcMap[order[j]] };
    }
    return null;
  }
  if (__AGG_PROVIDERS[musicItem.platform]) {
    return { key: musicItem.platform, raw: musicItem };
  }
  return null;
}

// 通用路由调用：返回 provider 结果（async 时为 Promise），无法路由返回 null。
// 传给 provider 的是快照浅拷贝——provider 改写入参不污染 FinalItem._src（冻结守则）。
function routeCall(musicItem, apiName, args) {
  var route = resolveAggRoute(musicItem);
  if (!route) return null;
  var provider = __AGG_PROVIDERS[route.key];
  if (!provider || typeof provider[apiName] !== 'function') return null;
  return provider[apiName].apply(provider, [shallowCopy(route.raw)].concat(args));
}

// §15 歌单/单曲导入（v1.1.0 工单二并入）

// 链接特征表：按固定检测序匹配域名/ID 正则；qq 域名最宽泛（cloud/分享页均带
// qq.com），放最后防误吞其它源。纯数字串视为网易云歌单 id（与 hints 文案一致）。
var IMPORT_URL_SIGNATURES = [
  { src: 'kuwo',    re: /kuwo\.cn|kuwo\.com/i },
  { src: 'migu',    re: /migu\.cn/i },
  { src: 'netease', re: /music\.163\.com|163cn\.tv/i },
  { src: 'qishui',  re: /qishui\.douyin\.com|douyin\.com/i },
  { src: 'kugou',   re: /kugou\.com/i },
  { src: 'qq',      re: /qq\.com/i },
  { src: 'netease', re: /^\s*\d+\s*$/ }
];

var IMPORT_SOURCE_LABELS = {
  kuwo: '酷我', migu: '咪咕', netease: '网易云',
  qishui: '汽水', kugou: '酷狗', qq: 'QQ'
};

// 链接特征路由：返回命中的源键；识别不出返回 null（交逐源尝试）
function detectImportSource(urlLike) {
  var s = String(urlLike == null ? '' : urlLike);
  if (!s.trim()) return null;
  for (var i = 0; i < IMPORT_URL_SIGNATURES.length; i++) {
    if (IMPORT_URL_SIGNATURES[i].re.test(s)) return IMPORT_URL_SIGNATURES[i].src;
  }
  return null;
}

// vendor 导入条目 → agg FinalItem：
//  - _src 快照放 vendor 条目原对象（其 id/_src/platform 形态即 vendor 自己的消费契约，
//    provider.getMediaSource 收到的与原生直用完全一致 → 导入曲目直接可聚合取链）；
//  - vendor 条目封面字段为 artwork，buildFinalItem 读 coverImg/cover → 补映射；
//  - 条目过 buildFinalItem 规范化（platform=agg、qualities 交集门、稳定 id）。
function importItemToFinal(srcKey, raw) {
  if (!raw || typeof raw !== 'object') return null;
  if (raw.id === undefined || raw.id === null || raw.id === '') return null;
  var r = raw;
  if (r.coverImg === undefined && r.cover === undefined && r.artwork !== undefined) {
    r = Object.assign({}, r, { coverImg: r.artwork });
  }
  return buildFinalItem(srcKey, r, null);
}

// 歌单导入结果规范化：兼容双形态 vendor 返回——
//  ① 数组（kuwo/kuwo/netease/qishui/kugou/qq 五源）；
//  ② 完整歌单对象 { id?, title?, artwork?, worksNum?, musicList }（migu v1.2.0+）。
// 输出宿主 IImportMusicSheetResult 口径：platform 改 agg、musicList 逐条过
// buildFinalItem、源歌单原始 id 保留于 _importedFrom（宿主无 id 时自生成 import-xxx）。
function normalizeImportedSheetResult(srcKey, urlLike, result) {
  var meta = {};
  var rawList = null;
  if (Array.isArray(result)) {
    rawList = result;
  } else if (result && typeof result === 'object' && Array.isArray(result.musicList)) {
    meta = result;
    rawList = result.musicList;
  }
  if (!rawList) return null;
  var seen = {};
  var musicList = [];
  for (var i = 0; i < rawList.length; i++) {
    var fi = importItemToFinal(srcKey, rawList[i]);
    if (!fi || seen[fi.id]) continue;
    seen[fi.id] = 1;
    musicList.push(fi);
  }
  if (!musicList.length) return null;
  var sheet = { platform: 'agg' };
  if (meta.id !== undefined && meta.id !== null && meta.id !== '') sheet.id = meta.id;
  if (meta.title) sheet.title = meta.title;
  if (meta.artwork) sheet.artwork = meta.artwork;
  if (meta.coverImg) sheet.artwork = sheet.artwork || meta.coverImg;
  sheet.worksNum = meta.worksNum || musicList.length;
  sheet.musicList = musicList;
  sheet._importedFrom = { platform: srcKey, urlLike: String(urlLike == null ? '' : urlLike) };
  if (meta.id !== undefined && meta.id !== null && meta.id !== '') {
    sheet._importedFrom.sheetId = meta.id;
  }
  return sheet;
}

// 单曲导入结果规范化：vendor 单曲条目过 buildFinalItem（同 importItemToFinal）
function normalizeImportedMusicResult(srcKey, result) {
  return importItemToFinal(srcKey, result);
}

// 未识别链接的固定源序逐源尝试（口径③ AGG_SOURCE_ORDER）：
//  - §14 门控：关闭的源直接跳过；
//  - 每源超时 5s，总闸 15s（超闸即停，报已收集到的错误）；
//  - 首个非空结果即止；全失败抛聚合错误（错误明细走 consoleWarn 留痕）。
async function importViaSequentialFallback(urlLike, apiName) {
  var deadline = now() + 15000;
  var errors = [];
  for (var i = 0; i < AGG_SOURCE_ORDER.length; i++) {
    var src = AGG_SOURCE_ORDER[i];
    var left = deadline - now();
    if (left <= 0) {
      errors.push(IMPORT_SOURCE_LABELS[src] + '：总闸 15s 已到，停止尝试');
      break;
    }
    if (!aggSourceEnabled(src)) {
      errors.push(IMPORT_SOURCE_LABELS[src] + '：源已关闭，跳过');
      continue;
    }
    var provider = __AGG_PROVIDERS[src];
    if (!provider || typeof provider[apiName] !== 'function') {
      errors.push(IMPORT_SOURCE_LABELS[src] + '：不支持 ' + apiName);
      continue;
    }
    try {
      var r = await withTimeout(
        provider[apiName].call(provider, String(urlLike)),
        Math.min(5000, left),
        'import-fallback ' + src + ' ' + apiName
      );
      var norm = (apiName === 'importMusicSheet')
        ? normalizeImportedSheetResult(src, urlLike, r)
        : normalizeImportedMusicResult(src, r);
      if (norm) return norm;
      errors.push(IMPORT_SOURCE_LABELS[src] + '：结果为空');
    } catch (e) {
      var msg = (e && e.message) ? e.message : String(e);
      errors.push(IMPORT_SOURCE_LABELS[src] + '：' + msg);
      consoleWarn('[agg] 导入逐源尝试 ' + src + ' 失败：' + msg);
    }
  }
  throw new Error('[agg] 导入失败（' + apiName + '）：未识别链接特征且逐源尝试均未命中——'
    + errors.join('；'));
}

// 识别命中的源直调对应 provider（15s 上限包裹）；结果规范化，空结果抛错
async function importDirect(src, urlLike, apiName) {
  var provider = __AGG_PROVIDERS[src];
  if (!provider || typeof provider[apiName] !== 'function') {
    throw new Error('[agg] 源 ' + IMPORT_SOURCE_LABELS[src] + ' 不支持 ' + apiName);
  }
  var r = await withTimeout(
    provider[apiName].call(provider, String(urlLike)),
    15000,
    'import ' + src + ' ' + apiName
  );
  var norm = (apiName === 'importMusicSheet')
    ? normalizeImportedSheetResult(src, urlLike, r)
    : normalizeImportedMusicResult(src, r);
  if (!norm) {
    throw new Error('[agg] 导入失败：' + IMPORT_SOURCE_LABELS[src] + ' 返回空结果');
  }
  return norm;
}

// 导入公共入口：链接特征路由 → 直调；识别不出 → 固定源序逐源尝试；
// 命中源已关闭（§14）→ 明确报错（不静默降级，避免把酷我链接错误导入到别的源）。
async function importByUrlLike(urlLike, apiName) {
  var s = String(urlLike == null ? '' : urlLike).trim();
  if (!s) throw new Error('[agg] 导入失败：链接为空');
  var src = detectImportSource(s);
  if (src !== null) {
    if (!aggSourceEnabled(src)) {
      throw new Error('[agg] 导入失败：链接特征命中 ' + IMPORT_SOURCE_LABELS[src]
        + '，但该源已在插件设置中关闭');
    }
    return importDirect(src, s, apiName);
  }
  consoleWarn('[agg] 导入：未识别链接特征（' + s.slice(0, 80) + '），按固定源序逐源尝试');
  return importViaSequentialFallback(s, apiName);
}

// 从 urlLike 提取源侧歌单 id（v1.2.1）：通用形态——纯数字串、?id=/&id= 参数、
// playlist/<id> 路径段。提取不出返回 null（交由整页重取兜底，不猜测）。
function extractSheetIdFromUrlLike(urlLike) {
  var s = String(urlLike == null ? '' : urlLike).trim();
  if (!s) return null;
  if (/^\d+$/.test(s)) return s;
  var m = s.match(/[?&]id=([^&#\s]+)/i);
  if (m && m[1]) return m[1];
  m = s.match(/playlist[\/=](\d+)/i);
  if (m && m[1]) return m[1];
  return null;
}

// 导入歌单回源路由（v1.2.1 恢复，修复 P1-20260909-02）：
// _importedFrom 存在时按 platform 回源取歌单数据。路由顺序：
//   ① urlLike 优先——可解析出源侧歌单 id 则直调源侧 getMusicSheetInfo({id}, page)
//     （支持翻页）；源侧 id 同时兜底读 _importedFrom.id（v1.1.0 格式）与 .sheetId；
//   ② 源侧 getMusicSheetInfo 不可用/失败/空 → urlLike 整页重取（重走源侧导入，
//     无翻页语义，isEnd=true）；
//   ③ 两级全失败 → { musicList: [] }（与不可路由行为一致）。
// 结果统一过 extractList 兜底 + wrapProviderMusicList（条目带 _src 快照可取链）；
// 源侧调用 15s 超时包裹；§14：源关闭 → 整源缺席。
async function routeImportedSheet(imp, sheetItem, page) {
  var key = imp.platform;
  if (!aggSourceEnabled(key)) return { musicList: [] }; // §14（v0.9.1）：源开关关闭 → 整源缺席
  var provider = __AGG_PROVIDERS[key];
  var urlLike = imp.urlLike != null && imp.urlLike !== '' ? String(imp.urlLike) : '';
  var sheetId = urlLike ? extractSheetIdFromUrlLike(urlLike) : null;
  if (sheetId === null && imp.id !== undefined && imp.id !== null && imp.id !== '') {
    sheetId = imp.id; // v1.1.0 {platform,id} 格式兜底
  }
  if (sheetId === null && imp.sheetId !== undefined && imp.sheetId !== null && imp.sheetId !== '') {
    sheetId = imp.sheetId;
  }
  if (sheetId !== null && provider && typeof provider.getMusicSheetInfo === 'function') {
    try {
      var raw = { id: sheetId };
      // 真实 vendor 的 getMusicSheetInfoImpl 读 sheetItem._ssrc[源].listId（六源同构，
      // vendor v1.6.x/v1.7.0 实测），仅 {id} 会抛「无可用的歌单详情源」——补 _ssrc
      // 形态（与 vendor 歌单条目 srcMapOf 同构），保证真网真正命中歌单详情接口。
      var ss = {};
      ss[key] = { listId: String(sheetId) };
      raw._ssrc = ss;
      if (sheetItem && sheetItem.title) raw.title = sheetItem.title;
      var res = await withTimeout(
        provider.getMusicSheetInfo.call(provider, shallowCopy(raw), page),
        15000, 'imported-sheet ' + key
      );
      if (res) {
        if (!Array.isArray(res.musicList)) {
          var alt = extractList(res);
          if (Array.isArray(alt) && alt.length) {
            res = { musicList: alt, isEnd: res.isEnd === true };
          }
        }
        if (Array.isArray(res.musicList)) {
          // vendor 明确返回数组（含空，如 page>1 的 isEnd 空页）→ 原样回传，
          // 不得当失败落整页重取，否则翻页会重复返回全量列表
          return wrapProviderMusicList(res, key);
        }
      }
    } catch (e) {
      consoleWarn('[agg] 导入歌单回源（' + IMPORT_SOURCE_LABELS[key] + '）失败：'
        + ((e && e.message) ? e.message : String(e)));
    }
  }
  // 整页重取兜底仅在 page 1（或未传页码）执行：page>1 的空数组响应是 vendor 的
  // 正常翻页语义（isEnd 空页），若再重取会把全量列表重复塞进第 2 页
  if (urlLike && (page == null || page <= 1) && provider && typeof provider.importMusicSheet === 'function') {
    try {
      var again = await withTimeout(
        provider.importMusicSheet.call(provider, urlLike),
        15000, 'imported-sheet-refetch ' + key
      );
      var norm = normalizeImportedSheetResult(key, urlLike, again);
      if (norm && Array.isArray(norm.musicList) && norm.musicList.length) {
        return { isEnd: true, musicList: norm.musicList }; // 整页重取无翻页语义
      }
    } catch (e) {
      consoleWarn('[agg] 导入歌单整页重取（' + IMPORT_SOURCE_LABELS[key] + '）失败：'
        + ((e && e.message) ? e.message : String(e)));
    }
  }
  return { musicList: [] };
}

// §13 下载矩阵（v0.7.0 并入）——插件 API 层，弹窗 UI 由宿主后续接入

// 无损族档位（默认扩展名 .flac；atmos_plus/dolby 同族容器口径与 LOSSLESS_MAGIC_TIERS 一致）
var AGG_LOSSLESS_EXT_TIERS = ['flac', 'flac24bit', 'hires', 'master', 'atmos', 'atmos_plus', 'dolby'];
var AGG_KNOWN_EXTS = ['mp3', 'flac', 'm4a', 'aac', 'ogg', 'wav', 'ape', 'wma'];

// 下载文件名非法字符（Windows 保留字符 + 控制符）→ 空格
var AGG_FILENAME_BAD_RE = /[\\/:*?"<>|\x00-\x1f]/g;

// 扩展名判定：qualities.format 命中已知扩展名优先；否则无损族 .flac / 有损族 .mp3
function downloadExtOf(quality, format) {
  var f = format ? String(format).toLowerCase().replace(/^\./, '') : '';
  if (AGG_KNOWN_EXTS.indexOf(f) >= 0) return f;
  return AGG_LOSSLESS_EXT_TIERS.indexOf(String(quality)) >= 0 ? 'flac' : 'mp3';
}

// 文件名净化：非法字符 → 空格、空白折叠、去首尾空白与点（防 Windows 尾点截断）
function sanitizeFilenamePart(s) {
  var out = String(s == null ? '' : s).replace(AGG_FILENAME_BAD_RE, ' ').replace(/\s+/g, ' ').trim();
  out = out.replace(/^[.\s]+/, '').replace(/[.\s]+$/, '');
  return out;
}

// 建议文件名（§13）：`歌手 - 歌名 (音质).扩展名`；无歌手则 `歌名 (音质).扩展名`。
// quality 缺省回退 downloadQuality 配置（再回退 320k）。
function suggestFilenameOf(musicItem, quality) {
  var q = (quality !== undefined && quality !== null && quality !== '') ? String(quality) : downloadQualityOf();
  var qv = (musicItem && musicItem.qualities && musicItem.qualities[q]) || null;
  var ext = downloadExtOf(q, qv && qv.format);
  var artist = sanitizeFilenamePart(musicItem && musicItem.artist);
  var title = sanitizeFilenamePart(musicItem && (musicItem.title || musicItem.id)) || 'unknown';
  return (artist ? artist + ' - ' : '') + title + ' (' + q + ').' + ext;
}

/**
 * 下载矩阵（§13，零网络）：从 FinalItem._src 各源快照汇总「源 × 音质 × 大小」。
 * 数据口径：size 取各源 search/getMusicInfo 回填的 raw.qualities[q].size（经
 * parseSizeToBytes 归一字节，可能为 null=源未回填）；bitrate/format 原样透出。
 * 已关闭源（§14 开关）不出现在矩阵行，仅在 sources 摘要中标 enabled=false；
 * QQ 行标注 credentialRequired/credentialReady（未就绪时该源不参与实际取链）。
 * 非聚合条目（platform != 'agg'）按单源条目处理（qualities 即其自身声明）。
 */
function buildDownloadMatrix(musicItem) {
  if (!musicItem || typeof musicItem !== 'object') {
    return { ok: false, reason: 'invalid-music-item' };
  }
  var isAgg = musicItem.platform === 'agg';
  var entries = [];
  if (isAgg) {
    var srcMap = musicItem._src || {};
    for (var i = 0; i < AGG_SOURCE_ORDER.length; i++) {
      var k = AGG_SOURCE_ORDER[i];
      if (!srcMap[k]) continue;
      entries.push({
        key: k, label: AGG_SOURCE_LABELS[k],
        enabled: aggSourceEnabled(k),
        credentialReady: k === 'qq' ? qqCredentialReady() : true
      });
    }
  } else if (__AGG_PROVIDERS[musicItem.platform]) {
    entries.push({
      key: musicItem.platform,
      label: AGG_SOURCE_LABELS[musicItem.platform] || musicItem.platform,
      enabled: true, credentialReady: true
    });
  } else {
    return { ok: false, reason: 'unknown-platform:' + musicItem.platform };
  }
  var matrix = [];
  var declared = {};
  for (var qi = 0; qi < AGG_QUALITY_ORDER.length; qi++) {
    var q = AGG_QUALITY_ORDER[qi];
    var row = { quality: q, sources: [] };
    for (var ei = 0; ei < entries.length; ei++) {
      var en = entries[ei];
      if (!en.enabled) continue;
      var raw = isAgg ? (musicItem._src || {})[en.key] : musicItem;
      var qv = (raw && raw.qualities && raw.qualities[q]) || null;
      if (!qv) continue;
      // P1-20260909-01：下载面音质钳制——矩阵行统一「声明表 ∩ 原始声明」口径
      // （_src 原始声明可能含虚标档如汽水 320k/192k，SOURCE_HOST_QUALITIES 已收敛
      // 掉的档位不得从下载入口触发取链；播放面 _qualitySources 交集门已同口径）
      if (isAgg) {
        var hostQs1 = SOURCE_HOST_QUALITIES[en.key];
        if (!hostQs1 || hostQs1.indexOf(q) < 0) continue;
      }
      declared[q] = true;
      row.sources.push({
        source: en.key, label: en.label,
        size: parseSizeToBytes(qv.size),
        sizeText: qv.size !== undefined && qv.size !== null ? String(qv.size) : null,
        bitrate: qv.bitrate !== undefined && qv.bitrate !== null ? qv.bitrate : null,
        format: qv.format !== undefined && qv.format !== null ? String(qv.format) : null,
        credentialRequired: en.key === 'qq',
        credentialReady: en.credentialReady
      });
    }
    if (row.sources.length) matrix.push(row);
  }
  var srcSummary = [];
  for (var si = 0; si < entries.length; si++) {
    srcSummary.push({
      key: entries[si].key, label: entries[si].label,
      enabled: entries[si].enabled, credentialReady: entries[si].credentialReady
    });
  }
  return {
    ok: true,
    itemId: musicItem.id,
    title: musicItem.title, artist: musicItem.artist, album: musicItem.album,
    sources: srcSummary,
    matrix: matrix,
    declaredQualities: Object.keys(declared),
    filenameRule: '歌手 - 歌名 (音质).扩展名',
    note: 'size 为各源 search/getMusicInfo 回填的标称大小（字节，null=源未回填）；' +
      '字节级下载进度由宿主下载器产生（宿主直接消费 qualities.size）；' +
      '取链阶段状态可经 getDownloadUrl(musicItem, quality, source?, onStage?) 的 onStage 回调观察' +
      '（queued → resolving → done/failed）。'
  };
}

/**
 * 构造「单源候选视图」（§13 指定源下载）：同一 scheduleFetch 调度器，不另起炉灶。
 * 返回新对象（不写入参——宿主经 immer 冻结入参；且冻结守则扫描禁止改写 musicItem）。
 */
function singleSourceView(musicItem, srcKey, quality) {
  var view = {};
  for (var pk in musicItem) {
    if (Object.prototype.hasOwnProperty.call(musicItem, pk)) view[pk] = musicItem[pk];
  }
  var srcOnly = {};
  srcOnly[srcKey] = (musicItem._src || {})[srcKey];
  var qSrcOnly = {};
  qSrcOnly[quality] = [srcKey];
  view._src = srcOnly;
  view._qualitySources = qSrcOnly;
  view._default = srcKey;
  return view;
}

// §15 源自检 agg:doctor（v0.7.0 并入）——手动触发；探测不污染竞速健康度记账
// （HEALTH 仅由调度器 runLane 记账，本模块只读，不调用 recordSuccess/recordFailure）

var AGG_DOCTOR_PROBE_MS = 1500;

// 单源连通性探测：搜索接口轻量探测（1 页 music 搜索，1.5s 预算）。
// resolved=接口通（不要求有结果）；rejected/超时=异常；接口缺失=no-api。
async function doctorProbeSource(srcKey) {
  var p = __AGG_PROVIDERS[srcKey];
  if (!p || typeof p.search !== 'function') return { status: 'no-api' };
  var t0 = now();
  try {
    await withTimeout(Promise.resolve(p.search('聚合自检', 1, 'music')), AGG_DOCTOR_PROBE_MS, 'doctor ' + srcKey);
    return { status: 'ok', latencyMs: now() - t0 };
  } catch (e) {
    var msg = errMsg(e);
    return { status: msg.indexOf('timeout') >= 0 ? 'timeout' : 'fail', latencyMs: now() - t0, error: msg };
  }
}

// D7（v1.0.0）MV 能力面探测：固定测试曲目（固定搜索词首条）→ provider.getMvSource
// 480p 低档（省流量）。纯诊断：不写 MV 健康度记账（与连通性探测同语义）。
// status: ok=取到 url / no-track=搜索无曲目 / no-mv=曲目无 MV 或未取到 url /
//         timeout / fail / no-api=源无 getMvSource 能力。
var _doctorMvLatency = {}; // srcKey -> 最近 5 次 MV 探测时延（跑动平均）
var AGG_DOCTOR_MV_KEYWORD = '晴天';

function doctorMvAvgOf(srcKey) {
  var arr = _doctorMvLatency[srcKey];
  if (!arr || !arr.length) return null;
  var s = 0;
  for (var i = 0; i < arr.length; i++) s += arr[i];
  return Math.round(s / arr.length);
}

async function doctorProbeMvSource(srcKey) {
  var p = __AGG_PROVIDERS[srcKey];
  if (!p) return { status: 'missing', note: 'vendor 未注册，未探测' }; // 不计入 probed
  if (typeof p.getMvSource !== 'function') return { status: 'no-api' };
  var t0 = now();
  try {
    var sr = await withTimeout(
      Promise.resolve(p.search(AGG_DOCTOR_MV_KEYWORD, 1, 'music')),
      AGG_DOCTOR_PROBE_MS, 'doctor mv-search ' + srcKey);
    var items = extractList(sr);
    if (!items.length) return { status: 'no-track', latencyMs: now() - t0 };
    var res = await withTimeout(
      Promise.resolve(p.getMvSource(shallowCopy(items[0]), '480p')),
      AGG_MV_RESOLVE_MS, 'doctor mv ' + srcKey);
    var lat = now() - t0;
    if (res && typeof res === 'object' && res.url) {
      var arr = _doctorMvLatency[srcKey] || (_doctorMvLatency[srcKey] = []);
      arr.push(lat);
      while (arr.length > 5) arr.shift();
      return { status: 'ok', latencyMs: lat, videoQuality: res.videoQuality !== undefined ? res.videoQuality : null };
    }
    return { status: 'no-mv', latencyMs: lat };
  } catch (e) {
    var msg = errMsg(e);
    return { status: msg.indexOf('timeout') >= 0 ? 'timeout' : 'fail', latencyMs: now() - t0, error: msg };
  }
}

/**
 * 源自检总入口（§15）：各源报告 = 开关状态 / 凭据就绪度（qq/kugou/netease）/
 * 健康度（含熔断剩余时间）/ 可用音质档位（SOURCE_HOST_QUALITIES 声明口径）/
 * 连通性探测（仅对已开启源并发探测）。纯诊断：不写任何 HEALTH/缓存状态。
 */
async function aggDoctor() {
  var uv = aggUserVariables();
  var bases = [];
  var probes = [];
  var mvProbes = [];
  for (var i = 0; i < AGG_SOURCE_ORDER.length; i++) {
    var k = AGG_SOURCE_ORDER[i];
    var enabled = aggSourceEnabled(k);
    var st = healthStateOf(k);
    var credential = { required: false, ready: true };
    if (k === 'qq') {
      credential = { required: true, ready: qqCredentialReady(), keys: ['qqAuthst', 'qqCookie'] };
    } else if (k === 'kugou') {
      credential = { required: false, configured: !!(uv.kugouCookie && String(uv.kugouCookie).length >= 8), keys: ['kugouCookie'] };
    } else if (k === 'netease') {
      credential = { required: false, configured: !!(uv.neteaseCookie && String(uv.neteaseCookie).length >= 8), keys: ['neteaseCookie'] };
    }
    var base = {
      key: k,
      label: AGG_SOURCE_LABELS[k],
      enabled: enabled,
      credential: credential,
      health: {
        score: st.score,
        failStreak: st.failStreak,
        tripped: isTripped(k),
        reopenInMs: st.openUntil > now() ? (st.openUntil - now()) : 0
      },
      qualities: SOURCE_HOST_QUALITIES[k].slice(),
      connectivity: { status: 'disabled', note: '源已关闭，未探测' }
    };
    bases.push(base);
    if (enabled) {
      probes.push(doctorProbeSource(k));
      mvProbes.push(doctorProbeMvSource(k)); // D7：MV 能力面探测（仅开启源）
    } else {
      probes.push(null);
      mvProbes.push(null);
    }
  }
  var probeResults = await Promise.all(probes);
  var mvResults = await Promise.all(mvProbes);
  var okCount = 0;
  var mvOkCount = 0;
  var mvProbedCount = 0;
  for (var r = 0; r < bases.length; r++) {
    var pr = probeResults[r];
    if (pr) {
      bases[r].connectivity = pr;
      if (pr.status === 'ok') okCount++;
    }
    var mr = mvResults[r];
    if (mr) {
      if (mr.status === 'ok') {
        mvOkCount++;
        mr.avgLatencyMs = doctorMvAvgOf(bases[r].key); // 跑动平均（窗口 5）
      }
      bases[r].mv = mr;
      // probed 语义：仅计实际执行了 MV 解析尝试的源（no-api / missing / disabled 不计）
      if (mr.status !== 'no-api' && mr.status !== 'missing') mvProbedCount++;
    } else {
      bases[r].mv = { status: 'disabled', note: '源已关闭，未探测' };
    }
  }
  return {
    ok: true,
    version: AGG_VERSION,
    generatedAt: new Date().toISOString(),
    probeBudgetMs: AGG_DOCTOR_PROBE_MS,
    sources: bases,
    summary: { total: bases.length, enabledOk: okCount, enabledTotal: probes.filter(function (x) { return x !== null; }).length,
      mv: { ok: mvOkCount, probed: mvProbedCount } },
    scheduler: {
      totalBudgetMs: FETCH_BUDGET.TOTAL_MS,
      firstWindow: FETCH_BUDGET.FIRST,
      fallbackWindow: FETCH_BUDGET.FALLBACK
    },
    note: '探测为诊断用轻量搜索（1.5s 预算），结果不写入竞速健康度记账；' +
      'resolved=ok 表示接口连通（不要求有搜索结果）。' +
      'mv 探测（v1.0.0 D7）：固定测试曲目（搜索「' + AGG_DOCTOR_MV_KEYWORD + '」首条）' +
      '逐源调 getMvSource（480p 低档，单源 ' + AGG_MV_RESOLVE_MS + 'ms 预算），' +
      '不写入健康度记账；no-mv=该源曲目无 MV 或未取到 url（汽水无 MV 能力属预期）；' +
      '4k 档仅咪咕/QQ 实档，其余源请求 4k 会内部回落并由 videoQuality 如实标注。'
  };
}

// 插件主体（IPluginDefine）

