// ---- 移植函数 12 个（v0.4.1 原文）----
// [v1.3.2 F1] VIP 显示标识黑名单：聚合结果对外不透出任何 VIP/付费字段（宿主按
// fee===1/isVip 等点亮 VIP 角标）。仅过滤 FinalItem 顶层展示字段——vendor 取链
// 一律读 _src 快照（快照在 passThroughExtras 之前冻结，不受影响），核心层也无
// 任何代码读顶层 fee/vip 做取链判断，故本过滤不触碰播放取链逻辑。
var VIP_FIELD_BLOCKLIST = {
  fee: 1, isVip: 1, is_vip: 1, vip: 1, vipType: 1, vipFlag: 1, vipLevel: 1, vip_level: 1,
  vipIcon: 1, vip_icon: 1, vipPoints: 1, pay: 1, payInfo: 1, pay_info: 1,
  payType: 1, pay_type: 1, paid: 1, charge: 1, chargeInfo: 1, charge_info: 1,
  privilege: 1, privileges: 1, isPay: 1, is_pay: 1, needVip: 1, need_vip: 1, onlyVip: 1
};

function passThroughExtras(finalItem, raw) {
  if (!finalItem || !raw || typeof raw !== 'object') return finalItem;
  for (var k in raw) {
    if (!Object.prototype.hasOwnProperty.call(raw, k)) continue;
    if (typeof k !== 'string' || k.length === 0 || k.charAt(0) === '_') continue;
    if (k in finalItem) continue;  // FinalItem 固定键优先，不被快照覆盖
    // [v1.3.2 F1] VIP 显示标识统一过滤（黑名单命中即跳过，不进对外透传面）
    if (VIP_FIELD_BLOCKLIST[k]) continue;
    var v = raw[k];
    if (typeof v === 'function') continue;
    finalItem[k] = v;
  }
  return finalItem;
}

function attachToplistSrc(srcKey, item) {
  if (!item || typeof item !== 'object') return item;
  // 快照 = 源侧形态（id 须为源侧榜单 id），不含 _src（避免自引用循环）
  var snap = shallowCopy(item);
  var srcMap = {};
  srcMap[srcKey] = snap;
  item._src = srcMap;
  return item;
}

function resolveToplistSource(toplist) {
  if (!toplist || typeof toplist !== 'object') return null;
  // 1) 优先 _src 快照
  if (toplist._src && typeof toplist._src === 'object') {
    for (var i = 0; i < AGG_SOURCE_ORDER.length; i++) {
      var k = AGG_SOURCE_ORDER[i];
      if (toplist._src[k]) return { key: k, raw: toplist._src[k] };
    }
  }
  // 2) 兜底：id 前缀（兼容源 provider 直发的条目，未经过 attachToplistSrc）
  var key = sourcePrefixOf(toplist.id);
  if (key && __AGG_PROVIDERS[key]) {
    return { key: key, raw: toplist };
  }
  return null;
}

function sourcePrefixOf(id) {
  if (typeof id !== 'string' || !id) return null;
  if (id.indexOf('kw_bang_') === 0) return 'kuwo';
  if (id.indexOf('kgrank~') === 0) return 'kugou';
  if (id.indexOf('qqtop~') === 0) return 'qq';
  if (id.indexOf('ne~') === 0) return 'netease';
  if (id.indexOf('mg-') === 0) return 'migu';
  if (id.indexOf('qs-') === 0) return 'qishui';
  // 统一分类 id：'agg-chart-{key}'（聚合卡，无源前缀）/ 'agg-chart-{key}-{src}'（单源卡）。
  // v1.3.0：key 可含 '-'（如 japan-korea / rock-folk），不能按 '-' 段数切分 → 走 parseAggChartId
  if (id.indexOf('agg-chart-') === 0) {
    var chartRef = parseAggChartId(id);
    return chartRef && chartRef.src ? chartRef.src : null;
  }
  return null;
}

function findCategoryByKey(key) {
  for (var i = 0; i < CHART_CATEGORY.length; i++) {
    if (CHART_CATEGORY[i].key === key) return CHART_CATEGORY[i];
  }
  return null;
}

// ---- 聚合榜 id 解析（v1.3.0）----
// 'agg-chart-{key}' → { key, src: null }（聚合卡，详情走跨源名次合并）
// 'agg-chart-{key}-{src}' → { key, src }（单源卡，详情回源）
// key 可含 '-'（如 japan-korea），故按 AGG_SOURCE_ORDER 后缀匹配，不按 '-' 切段。
function parseAggChartId(id) {
  if (typeof id !== 'string' || id.indexOf('agg-chart-') !== 0) return null;
  var rest = id.substring('agg-chart-'.length);
  if (!rest) return null;
  for (var i = 0; i < AGG_SOURCE_ORDER.length; i++) {
    var suffix = '-' + AGG_SOURCE_ORDER[i];
    if (rest.length > suffix.length && rest.lastIndexOf(suffix) === rest.length - suffix.length) {
      return { key: rest.substring(0, rest.length - suffix.length), src: AGG_SOURCE_ORDER[i] };
    }
  }
  return { key: rest, src: null };
}

// ---- 聚合榜单算法（v1.3.0）：按固定分类取各源固定汇总榜单 → 跨源名次合并 ----
// 口径：不是「取全量→按分类聚合」。每个分类只拉 CHART_CATEGORIES 里 pin 的各源固定榜单
// page1（aggWithTimeout 单源 8s 预算，失败源缺席不拖垮整榜），再按名次分跨源合并。
var AGG_CHART_SOURCE_BUDGET_MS = 8000;   // 单源拉榜预算（超时该源缺席）
var AGG_CHART_TTL_MS = 30 * 60 * 1000;   // 聚合榜会话缓存 TTL
var AGG_CHART_CACHE_MAX = 8;             // 聚合榜缓存 LRU 容量（按分类计）
var _aggChartCache = [];

function chartTtlMsOf() {
  return _aggTestOverrides.chartTtlMs != null ? _aggTestOverrides.chartTtlMs : AGG_CHART_TTL_MS;
}

function chartCacheGet(key) {
  for (var i = 0; i < _aggChartCache.length; i++) {
    var e = _aggChartCache[i];
    if (e.key === key) {
      if (Date.now() - e.at > chartTtlMsOf()) { _aggChartCache.splice(i, 1); return null; }
      if (i > 0) { _aggChartCache.splice(i, 1); _aggChartCache.unshift(e); }
      return e.list;
    }
  }
  return null;
}

function chartCachePut(entry) {
  for (var i = 0; i < _aggChartCache.length; i++) {
    if (_aggChartCache[i].key === entry.key) { _aggChartCache.splice(i, 1); break; }
  }
  _aggChartCache.unshift(entry);
  while (_aggChartCache.length > AGG_CHART_CACHE_MAX) _aggChartCache.pop();
}

// buildMergedChartList(cat) → Promise<FinalItem[]>
// 1) 并发取各源固定榜单 page1（去重后 N 条，名次分 rankScore = (N - idx) / N）
// 2) 复用搜索聚合簇栈（normalizeItem → bucketKeyOf → clusterAndMerge）跨源同曲合并
// 3) 条目得分 = 名次分均值（同源重复取更高名次）+ 0.2 × (命中源数 - 1)，降序
// 4) buildMergedFinalItem 多源 _src 快照 + _variants（跨源取链回退与搜索同构）+ rank 元数据
function buildMergedChartList(cat) {
  var srcKeys = [];
  var snaps = {};
  for (var i = 0; i < AGG_SOURCE_ORDER.length; i++) {
    var sk = AGG_SOURCE_ORDER[i];
    if (!aggSourceEnabled(sk)) continue; // §14：源开关关闭 → 该源缺席
    var ce = cat.charts[sk];
    if (!ce) continue;                   // 分类下未 pin 该源 → 不拉
    srcKeys.push(sk);
    snaps[sk] = {
      id: ce.id,
      title: cat.title + ' · ' + (AGG_SOURCE_LABELS[sk] || sk),
      type: ce.type || (sk === 'netease' ? 0 : 1)
    };
  }
  if (!srcKeys.length) return Promise.resolve([]);
  var jobs = srcKeys.map(function (sk) {
    var provider = __AGG_PROVIDERS[sk];
    if (!provider || typeof provider.getTopListDetail !== 'function') {
      return Promise.resolve({ key: sk, list: [], error: 'no-api' });
    }
    return Promise.resolve().then(async function () {
      // aggWithTimeout 返回标记对象 {__timeout|__value|__error}，此处解包（缺席语义）
      var r = await aggWithTimeout(provider.getTopListDetail(shallowCopy(snaps[sk]), 1), AGG_CHART_SOURCE_BUDGET_MS);
      if (r.__timeout) return { key: sk, list: [], error: 'timeout' };
      if (r.__error) throw r.__error;
      var res = r.__value;
      var list = (res && Array.isArray(res.musicList)) ? res.musicList : [];
      return { key: sk, list: list, error: null };
    }).then(function (rec) {
      return rec;
    }, function (e) {
      consoleWarn('[agg] mergedChart ' + cat.key + '/' + sk + ' 失败: ' + errMsg(e));
      return { key: sk, list: [], error: errMsg(e) };
    });
  });
  return Promise.all(jobs).then(function (results) {
    var norms = [];
    var okSources = 0;
    for (var r = 0; r < results.length; r++) {
      var rec = results[r];
      if (rec.error || !rec.list.length) continue;
      var deduped = dedupeBySid(rec.list);   // 源内去重保序
      var n = deduped.length;
      if (!n) continue;
      okSources++;
      for (var d = 0; d < n; d++) {
        var norm = normalizeItem(rec.key, deduped[d]);
        if (!norm) continue;
        norm.seq = d;
        norm.rankScore = (n - d) / n;        // 名次分：榜首 1.0，末位 1/N
        norms.push(norm);
      }
    }
    if (!okSources || !norms.length) return [];
    var groups = clusterAndMerge(norms);     // 跨源同曲并组（软匹配阈值与搜索一致）
    var scored = [];
    for (var g = 0; g < groups.length; g++) {
      var members = groups[g].members;
      var best = {};                         // 同源重复取更高名次
      for (var m = 0; m < members.length; m++) {
        var it = members[m];
        if (best[it.srcKey] === undefined || it.rankScore > best[it.srcKey]) {
          best[it.srcKey] = it.rankScore;
        }
      }
      var hit = 0, sum = 0;
      for (var sk2 in best) { hit++; sum += best[sk2]; }
      scored.push({
        group: groups[g],
        score: sum / hit + 0.2 * (hit - 1),  // 名次分均值 + 0.2×(命中源数-1)
        hitSourceCount: hit
      });
    }
    scored.sort(function (a, b) { return b.score - a.score; });
    var finals = [];
    for (var s = 0; s < scored.length; s++) {
      var fi = buildMergedFinalItem(scored[s].group.members, null);
      if (!fi) continue;
      fi._chartScore = Math.round(scored[s].score * 10000) / 10000;
      fi._hitSourceCount = scored[s].hitSourceCount;
      fi._chartKey = cat.key;
      finals.push(fi);
    }
    return finals;
  });
}

function pageMergedChart(full, pno) {
  var start = (pno - 1) * AGG_PAGE_SIZE;
  var slice = full.slice(start, start + AGG_PAGE_SIZE);
  return { isEnd: start + AGG_PAGE_SIZE >= full.length, musicList: slice };
}

function getMergedChartDetail(catKey, pno) {
  var cat = findCategoryByKey(catKey);
  if (!cat) return Promise.resolve({ isEnd: true, musicList: [] });
  var cached = chartCacheGet(catKey);
  if (cached) return Promise.resolve(pageMergedChart(cached, pno));
  return buildMergedChartList(cat).then(function (full) {
    chartCachePut({ key: catKey, at: Date.now(), list: full });
    return pageMergedChart(full, pno);
  }, function (e) {
    consoleWarn('[agg] mergedChart ' + catKey + ' 失败: ' + errMsg(e));
    return { isEnd: true, musicList: [] };
  });
}

function buildUnifiedChartGroups() {
  var out = [];
  for (var i = 0; i < CHART_CATEGORIES.length; i++) {
    var cat = CHART_CATEGORIES[i];
    var data = [];
    // 1) 聚合卡（v1.3.0 主路径）：跨源名次合并榜，id 'agg-chart-{key}'，
    //    详情走 getTopListDetail 合并分支；_src 快照携带各源固定榜单 id 供合并拉取。
    var hitCount = 0;
    for (var j = 0; j < AGG_SOURCE_ORDER.length; j++) {
      if (aggSourceEnabled(AGG_SOURCE_ORDER[j]) && cat.charts[AGG_SOURCE_ORDER[j]]) hitCount++;
    }
    if (hitCount > 0) {
      var msrc = {};
      for (var j2 = 0; j2 < AGG_SOURCE_ORDER.length; j2++) {
        var sk = AGG_SOURCE_ORDER[j2];
        if (!aggSourceEnabled(sk)) continue;
        var ce = cat.charts[sk];
        if (!ce) continue;
        msrc[sk] = {
          id: ce.id,
          title: cat.title + ' · ' + (AGG_SOURCE_LABELS[sk] || sk),
          type: ce.type || (sk === 'netease' ? 0 : 1)
        };
      }
      data.push({
        id: 'agg-chart-' + cat.key,
        title: cat.title,
        description: '聚合榜 · ' + hitCount + ' 源名次合并',
        type: 1,
        _mergedChart: true,
        _mergedKey: cat.key,
        _src: msrc
      });
    }
    // [v1.3.2 F2] 单源卡（次级浏览入口）不再生成：分类列表只保留聚合榜一张卡，
    // 用户视角每分类只有一份榜单；单源回源能力保留在 getTopListDetail 的
    // parseAggChartId '-{src}' 兼容分支，不受本改动影响。
    if (data.length) out.push({ title: cat.title, data: data });
  }
  return out;
}

function findUnifiedTag(tagId) {
  if (typeof tagId !== 'string') return null;
  if (tagId.indexOf('agg-tag-') !== 0) return null;
  var key = tagId.substring('agg-tag-'.length);
  for (var i = 0; i < TAG_MAPPING.length; i++) {
    if (TAG_MAPPING[i].key === key) return TAG_MAPPING[i];
  }
  return null;
}

function dedupeBySid(musicList) {
  if (!Array.isArray(musicList)) return [];
  var seen = {};
  var out = [];
  for (var i = 0; i < musicList.length; i++) {
    var it = musicList[i];
    if (!it || typeof it !== 'object') continue;
    var sid = it.id;
    if (typeof sid !== 'string' || !sid) sid = '__noid_' + i;
    if (seen[sid]) continue;
    seen[sid] = 1;
    out.push(it);
  }
  return out;
}

function buildSheetFinalItem(srcKey, raw) {
  if (!raw || typeof raw !== 'object') return null;
  var stableId = stableIdOf(srcKey, raw);
  if (!stableId) return null;
  var snap = shallowCopy(raw);
  // 强制单一源快照：避免源 provider 自带回 _src 污染
  var srcMap = {};
  srcMap[srcKey] = snap;
  var cover = raw.artwork !== undefined ? raw.artwork
    : (raw.coverImg !== undefined ? raw.coverImg : raw.cover);
  var fi = {
    id: stableId,
    title: raw.title,
    artist: raw.artist,
    artwork: cover,   // 宿主 SheetItem 首选读法
    coverImg: cover,  // 宿主兜底读法 + 榜单卡片（topListItem.tsx）读法
    worksNum: raw.worksNum !== undefined ? raw.worksNum : raw.worksCount,
    playCount: raw.playCount,
    // v1.3.0：歌单分源展示（不混排）—— description 冠源名，宿主与用户可直接辨识来源
    description: (AGG_SOURCE_LABELS[srcKey] ? AGG_SOURCE_LABELS[srcKey] + ' · ' : '')
      + (raw.description != null ? String(raw.description) : ''),
    _src: srcMap,
    _srcOrder: [srcKey],
    _default: srcKey,
    platform: 'agg'
  };
  // S1/S3：白名单外字段透传（源自有展示字段如 worksCount 等；固定键与 '_' 内部键不受影响）
  return passThroughExtras(fi, raw);
}

function sourceTagPrefixOf(tagId) {
  if (typeof tagId !== 'string' || !tagId) return null;
  if (tagId.indexOf('agg-tag-') === 0) return null;  // 统一标签不在此路由
  if (tagId.indexOf('kw~') === 0) return 'kuwo';
  if (tagId.indexOf('ne~') === 0) return 'netease';
  if (tagId.indexOf('mg~') === 0) return 'migu';
  if (tagId.indexOf('kg~') === 0) return 'kugou';
  if (tagId.indexOf('qqtag~') === 0 || tagId.indexOf('qq~') === 0) return 'qq';
  if (tagId.indexOf('qs~') === 0 || tagId.indexOf('qs-') === 0) return 'qishui';
  return null;
}

function getSheetsBySourceTag(tag, pno) {
  var tagId = tag && typeof tag.id === 'string' ? tag.id : null;
  var srcKey = sourceTagPrefixOf(tagId);
  if (!srcKey) return Promise.resolve({ data: [], isEnd: true });
  if (!aggSourceEnabled(srcKey)) return Promise.resolve({ data: [], isEnd: true }); // §14（v0.9.1）：源开关关闭 → 源标签页整源缺席

  var transient = shallowCopy(tag);
  if (srcKey === 'kuwo') {
    transient.id = tagId.substring('kw~'.length);
  } else if (srcKey === 'qishui') {
    transient.id = tagId.substring(3);
  }
  transient.platform = srcKey;

  var provider = __AGG_PROVIDERS[srcKey];
  if (!provider || typeof provider.getRecommendSheetsByTag !== 'function') {
    // 降级：前缀源不可用 → 用第一个可用源（正常六源全注册时不触发）
    provider = null;
    for (var i = 0; i < AGG_SOURCE_ORDER.length; i++) {
      var k = AGG_SOURCE_ORDER[i];
      var p = __AGG_PROVIDERS[k];
      if (p && typeof p.getRecommendSheetsByTag === 'function' && aggSourceEnabled(k)) { provider = p; transient.platform = k; break; } // §14（v0.9.1）：降级选源跳过关闭源
    }
    if (!provider) return Promise.resolve({ data: [], isEnd: true });
    consoleWarn('[agg] 源标签 ' + tagId + ' 前缀源 ' + srcKey + ' 不可用，降级到 ' + transient.platform);
  }

  return Promise.resolve().then(function () { return provider.getRecommendSheetsByTag(transient, pno); })
    .then(function (res) {
      var data = (res && Array.isArray(res.data)) ? res.data : [];
      var out = [];
      for (var n = 0; n < data.length; n++) {
        var sfi = buildSheetFinalItem(transient.platform, data[n]);
        if (sfi) out.push(sfi);
      }
      return { data: out, isEnd: !!(res && res.isEnd === true) };
    }, function (e) {
      consoleWarn('[agg] 源标签 ' + tagId + ' 取歌单失败 (' + transient.platform + '): ' + errMsg(e));
      return { data: [], isEnd: true };
    });
}

function wrapProviderMusicList(res, srcKey) {
  if (!res || typeof res !== 'object') return { musicList: [] };
  var raw = res.musicList;
  if (!Array.isArray(raw)) return { isEnd: !!(res && res.isEnd === true), musicList: [] };
  var deduped = dedupeBySid(raw);
  var finals = [];
  for (var i = 0; i < deduped.length; i++) {
    var fi = buildFinalItem(srcKey, deduped[i]);
    if (fi) finals.push(fi);
  }
  return { isEnd: !!(res && res.isEnd === true), musicList: finals };
}

// 单源搜索包装：失败降级为 { key, items, isEnd, error }，不阻塞其余源。
// v0.2.0 契约：search 需感知源内翻页是否到底（isEnd），供聚合会话与透传层判定 isEnd。
function callProviderSearch(key, query, page, type) {
  var p = __AGG_PROVIDERS[key];
  try {
    return Promise.resolve(p.search(query, page, type)).then(function (res) {
      return { key: key, items: extractList(res), isEnd: !!(res && res.isEnd === true) };
    }, function (e) {
      return { key: key, items: [], isEnd: false, error: errMsg(e) };
    });
  } catch (e) {
    return Promise.resolve({ key: key, items: [], isEnd: false, error: errMsg(e) });
  }
}

// P1-7 歌词同步模块（v0.6.0 并入）
//   LyricRegistry（§9 登记表） / LyricParser（解析） / LyricFetcher（获取，
//   即升级后的 routeLyricChain） / LyricSyncer（同步）

var AGG_LYRIC_TTL_MS = 10 * 60 * 1000;   // 登记表 / 歌词缓存 TTL（方案 §9）
var AGG_LYRIC_REGISTRY_MAX = 128;        // 登记表 LRU 容量
var AGG_LYRIC_CACHE_MAX = 64;            // getLyric 解析缓存 LRU 容量（同步层缺省 lines）
var AGG_LYRIC_ALIGN_TOL_MS = 500;        // 翻译最近邻配对容差
var AGG_LYRIC_HYSTERESIS_MS = 200;       // 行切换滞回（边界防抖）
var AGG_LYRIC_SEEK_JUMP_MS = 1500;       // 相邻两次查询时刻差超过该值视为 seek，跳过滞回

// 通用小型 LRU+TTL 存储（登记表与歌词缓存共用；lru 头部为最新）
function aggLruMake() { return { map: {}, lru: [] }; }
function aggLruTouch(store, key) {
  var i = store.lru.indexOf(key);
  if (i > 0) { store.lru.splice(i, 1); store.lru.unshift(key); }
  else if (i < 0) store.lru.unshift(key);
}
function aggLruPut(store, key, val, cap, ttlMs) {
  aggLruTouch(store, key);
  store.map[key] = { val: val, ts: Date.now(), ttl: ttlMs };
  while (store.lru.length > cap) {
    var k = store.lru.pop();
    delete store.map[k];
  }
}
function aggLruGet(store, key) {
  var e = store.map[key];
  if (!e) return null;
  if (Date.now() - e.ts > e.ttl) {
    delete store.map[key];
    var i = store.lru.indexOf(key);
    if (i >= 0) store.lru.splice(i, 1);
    return null;
  }
  aggLruTouch(store, key);
  return e.val;
}

// LyricRegistry（§9）：键 platform|id → 胜出源 srcKey。
// 登记挂点：① 取链调度器 scheduleFetch 竞速成功返回处（getMediaSource 内）；
// ② 歌词路由链实际胜出源。getLyric 路由时命中登记源即优先（等效"以实际
// 竞速源覆盖 _default"——入参冻结不可改写，路由层排序实现同等语义）。
var _lyricRegistry = aggLruMake();
function aggLyricItemKey(musicItem) {
  return String(musicItem.platform || '') + '|' + String(musicItem.id === undefined || musicItem.id === null ? '' : musicItem.id);
}
function lyricRegistrySet(musicItem, srcKey) {
  if (!musicItem || typeof musicItem !== 'object' || !srcKey) return;
  aggLruPut(_lyricRegistry, aggLyricItemKey(musicItem), String(srcKey), AGG_LYRIC_REGISTRY_MAX, AGG_LYRIC_TTL_MS);
}
function lyricRegistryGet(musicItem) {
  if (!musicItem || typeof musicItem !== 'object') return null;
  return aggLruGet(_lyricRegistry, aggLyricItemKey(musicItem));
}

// ------------------------------ LyricParser ------------------------------

// LRC 时间标签：[mm:ss] / [mm:ss.xx] / [mm:ss.xxx] / 逗号小数 / [hh:mm:ss.xx]
var AGG_LRC_TIME_RE = /\[(\d{1,3}):(\d{1,2})(?::(\d{1,2}))?(?:[.,:](\d{1,3}))?\]/g;
// LRC 元数据行（整行仅一个标签才跳过；[00:12.34] 这类时间标签不受影响）
var AGG_LRC_META_RE = /^\[(ti|ar|al|by|au|offset|length|re|ve|tool|kana|hash|total|encoding):([^\]]*)\]\s*$/i;

function aggLrcTagMs(h, m, sec, frac) {
  // 两段式 [mm:ss.xx]：h=分、m=秒；三段式 [hh:mm:ss.xx]：h=时、m=分、sec=秒
  var ms = sec
    ? parseInt(h, 10) * 3600000 + parseInt(m, 10) * 60000 + parseInt(sec, 10) * 1000
    : parseInt(h, 10) * 60000 + parseInt(m, 10) * 1000;
  if (frac) {
    var f = String(frac);
    ms += parseInt(f, 10) * Math.pow(10, 3 - f.length);
  }
  return ms;
}

/**
 * parseLrc：行级 LRC → { lines, type:'lrc' }；无有效时间轴行返回 null。
 *  - 一行多时间戳展开为多条；offset 标签整体平移（[offset:+ms]，正值为提前，
 *    通行约定 offset 正值使歌词整体提前 → time = tag - offset）；
 *  - 元数据行 / 空文本行 / 异常行容错跳过；乱序输入排序。
 */
function parseLrc(text) {
  var rows = String(text || '').split(/\r?\n/);
  var lines = [];
  var offset = 0;
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    if (!row || !row.trim()) continue;
    var meta = row.match(AGG_LRC_META_RE);
    if (meta) {
      if (meta[1].toLowerCase() === 'offset') {
        var ov = parseInt(meta[2], 10);
        if (!isNaN(ov)) offset = ov;
      }
      continue;
    }
    AGG_LRC_TIME_RE.lastIndex = 0;
    var times = [];
    var m;
    while ((m = AGG_LRC_TIME_RE.exec(row))) {
      times.push(aggLrcTagMs(m[1], m[2], m[3], m[4]));
    }
    if (!times.length) continue; // 无时间戳的非元数据行（空行/广告行/异常行）跳过
    var txt = row.replace(AGG_LRC_TIME_RE, '').trim();
    if (!txt) continue;
    for (var t = 0; t < times.length; t++) {
      lines.push({ time: Math.max(0, times[t] - offset), text: txt });
    }
  }
  if (!lines.length) return null;
  lines.sort(function (a, b) { return a.time - b.time; });
  return { lines: lines, type: 'lrc' };
}

/**
 * parseWordByWord：逐字歌词统一行解析（provider 已完成解密，agg 层只做行解析）。
 * 兼容两种行形态（起始均为 [startMs,durMs]）：
 *   KRC-host：`[start,dur]词(绝对ms,时长ms)词(绝对ms,时长ms)`（酷狗/酷我/汽水直出）
 *   QRC/YRC：`[start,dur](绝对ms,时长ms,0)词(绝对ms,时长ms,0)词`（网易/QQ/咪咕）
 * 无词元的定时行视为翻译候选行（KRC language 包译文行 / QRC 译文行）。
 * 有效逐字行 ≥1 才返回 { lines, type:'逐字', transRows }，否则 null（调用方降级 LRC）。
 */
function parseWordByWord(text) {
  var rows = String(text || '').split(/\r?\n/);
  var lines = [];
  var transRows = [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    if (!row) continue;
    var m = row.match(/^\[(\d+),(\d+)\](.*)$/);
    if (!m) continue;
    var start = parseInt(m[1], 10);
    var dur = parseInt(m[2], 10);
    var body = m[3];
    if (body.indexOf('(') < 0) {
      var tt = body.trim();
      if (tt) transRows.push({ time: start, text: tt });
      continue;
    }
    var words = [];
    if (body.charAt(0) === '(') {
      // QRC/YRC 形态：词元在时刻组之后
      var reQ = /\((\d+),(\d+)(?:,\d+)?\)([^(\[]*)/g;
      var qm;
      while ((qm = reQ.exec(body))) {
        if (!qm[3]) continue;
        words.push({ start: parseInt(qm[1], 10), dur: parseInt(qm[2], 10), text: qm[3] });
      }
    } else {
      // KRC-host 形态：词元在时刻组之前
      var reK = /([^(\[]*)\((\d+),(\d+)(?:,\d+)?\)/g;
      var km;
      while ((km = reK.exec(body))) {
        if (!km[1]) continue;
        words.push({ start: parseInt(km[2], 10), dur: parseInt(km[3], 10), text: km[1] });
      }
    }
    if (!words.length) continue;
    words.sort(function (a, b) { return a.start - b.start; });
    var lineText = '';
    for (var w = 0; w < words.length; w++) lineText += words[w].text;
    lineText = lineText.trim();
    if (!lineText) continue;
    lines.push({ time: start, dur: dur, text: lineText, words: words });
  }
  if (!lines.length) return null;
  lines.sort(function (a, b) { return a.time - b.time; });
  return { lines: lines, type: '逐字', transRows: transRows };
}

// alignTranslation：翻译行与原文行最近邻时间配对（容差 500ms），未配上保留原文。
// 每条译文只配给最近的一条原文行（贪心 + 已消费标记，防同一条译文重复配多行）。
// 返回配对成功的行数。lines 原地补 translation 字段。
function alignTranslationRows(lines, transRows) {
  if (!lines || !lines.length || !transRows || !transRows.length) return 0;
  var consumed = {};
  var count = 0;
  for (var j = 0; j < transRows.length; j++) {
    var best = -1;
    var bestDiff = AGG_LYRIC_ALIGN_TOL_MS + 1;
    for (var i = 0; i < lines.length; i++) {
      if (consumed[i] || lines[i].translation !== undefined) continue;
      var d = Math.abs(transRows[j].time - lines[i].time);
      if (d <= AGG_LYRIC_ALIGN_TOL_MS && d < bestDiff) { bestDiff = d; best = i; }
    }
    if (best >= 0) {
      lines[best].translation = transRows[j].text;
      consumed[best] = true;
      count++;
    }
  }
  return count;
}

// 翻译文本（provider getLyric translation 字段，LRC 格式）解析后按时间配对
function alignTranslationText(lines, translationText) {
  if (!lines || !lines.length || !translationText) return 0;
  var parsed = parseLrc(String(translationText));
  if (!parsed) return 0;
  return alignTranslationRows(lines, parsed.lines);
}

// ------------------------------ LyricFetcher ------------------------------

// 歌词缓存：getLyric 解析结果（{ lines, type }）按 platform|id 缓存，供
// getCurrentLyricLine 缺省 lines 时取用（TTL 10min、LRU 64），并记录最近键。
var _lyricCache = aggLruMake();
var _lyricLastKey = null;
function lyricCachePut(musicItem, parsed) {
  if (!musicItem || typeof musicItem !== 'object' || !parsed || !parsed.lines) return;
  var k = aggLyricItemKey(musicItem);
  aggLruPut(_lyricCache, k, parsed, AGG_LYRIC_CACHE_MAX, AGG_LYRIC_TTL_MS);
  _lyricLastKey = k;
}

function aggLyricWbwText(wbw) {
  if (wbw === null || wbw === undefined) return '';
  if (typeof wbw === 'string') return wbw;
  if (wbw.rawLrc !== undefined && wbw.rawLrc !== null) return String(wbw.rawLrc);
  return '';
}

/**
 * 歌词路由链（LyricFetcher，v0.6.0 升级）：
 *  - mode='lyric'（getLyric）：逐源先试 getWordByWordLyric（解析出有效逐字行才
 *    采用，type='逐字'），失败/为空/不可解析降级 getLyric（type='lrc'；完全无
 *    时间轴的纯文本记 type='text'，整条空词则继续下一源）；全链失败抛错
 *    （宿主以 searchSimilarLyric 跨插件搜词兜底，§1.8 硬约束）。
 *  - mode='word'（getWordByWordLyric）：仅逐字通道，provider 结果原样透传
 *    （宿主逐字渲染语义不变）；无逐字词返回 null。
 *  - 源间顺序：登记表命中源 → _default → _srcOrder 顺延；
 *    实际胜出源回写登记表（含翻译/逐字解析与同步层缓存副作用）。
 */
async function routeLyricChain(musicItem, mode) {
  if (!musicItem || typeof musicItem !== 'object') {
    return mode === 'lyric' ? Promise.reject(new Error('[agg] 歌词路由：条目无效')) : null;
  }
  var order = [];
  if (musicItem.platform === 'agg') {
    var regHit = lyricRegistryGet(musicItem);
    if (regHit) order.push(regHit);
    if (musicItem._default) order.push(musicItem._default);
    var srcOrder = Array.isArray(musicItem._srcOrder) && musicItem._srcOrder.length
      ? musicItem._srcOrder : AGG_SOURCE_ORDER;
    for (var i = 0; i < srcOrder.length; i++) {
      if (order.indexOf(srcOrder[i]) < 0) order.push(srcOrder[i]);
    }
  } else if (__AGG_PROVIDERS[musicItem.platform]) {
    order.push(musicItem.platform);
  }
  var lastErr = null;
  for (var n = 0; n < order.length; n++) {
    var key = order[n];
    var srcMap = musicItem._src || {};
    if (musicItem.platform === 'agg' && !srcMap[key]) continue;
    if (musicItem.platform === 'agg' && !aggSourceEnabled(key)) continue; // §14：关闭源不参与歌词路由
    var provider = __AGG_PROVIDERS[key];
    if (!provider) continue;
    var raw = musicItem.platform === 'agg' ? shallowCopy(srcMap[key]) : shallowCopy(musicItem);
    // ① 逐字歌词优先
    if (typeof provider.getWordByWordLyric === 'function') {
      var wbw = null;
      try {
        wbw = await provider.getWordByWordLyric(raw);
      } catch (eW) {
        lastErr = eW;
        consoleWarn('[agg] getWordByWordLyric ' + key + ' 失败: ' + errMsg(eW));
      }
      if (wbw !== undefined && wbw !== null && wbw !== '') {
        var wText = aggLyricWbwText(wbw);
        var wParsed = parseWordByWord(wText);
        if (wParsed) {
          lyricRegistrySet(musicItem, key);
          alignTranslationRows(wParsed.lines, wParsed.transRows);
          lyricCachePut(musicItem, { lines: wParsed.lines, type: '逐字' });
          if (mode === 'word') return wbw; // 宿主逐字通道：provider 结果原样透传
          return {
            rawLrc: wText,
            lines: wParsed.lines,
            type: '逐字',
            _aggSource: key
          };
        }
        if (mode === 'word') return wbw; // 不可解析（宿主语义原样透传，由宿主判空丢弃）
        consoleWarn('[agg] getWordByWordLyric ' + key + ' 返回不可解析，降级 LRC');
      }
    }
    if (mode === 'word') continue; // 逐字通道不降级 LRC
    // ② 行级 LRC 降级
    if (typeof provider.getLyric !== 'function') continue;
    try {
      var r = await provider.getLyric(raw);
      if (r === undefined || r === null || r === '') continue; // 该源无词 → 下一源
      var lrcText = (typeof r === 'string') ? r
        : (r.rawLrc !== undefined && r.rawLrc !== null) ? String(r.rawLrc)
        : (r.lyric !== undefined && r.lyric !== null) ? String(r.lyric) : '';
      var transText = (r && typeof r === 'object' && r.translation !== undefined && r.translation !== null && r.translation !== '')
        ? String(r.translation) : null;
      var pl = parseLrc(lrcText);
      var lines, type;
      if (pl) {
        lines = pl.lines;
        type = 'lrc';
      } else {
        var plain = String(lrcText || '').trim();
        if (!plain) continue; // 整条无词 → 继续下一源（全败由外层抛错，宿主兜底）
        lines = [{ time: 0, text: plain }];
        type = 'text';
      }
      if (transText) alignTranslationText(lines, transText);
      lyricRegistrySet(musicItem, key);
      lyricCachePut(musicItem, { lines: lines, type: type });
      var out = { rawLrc: String(lrcText), lines: lines, type: type, _aggSource: key };
      if (transText !== null) out.translation = transText;
      return out;
    } catch (e) {
      lastErr = e;
      consoleWarn('[agg] getLyric ' + key + ' 失败: ' + errMsg(e));
    }
  }
  if (mode === 'lyric') {
    throw new Error('[agg] 所有可路由源的歌词均不可用' + (lastErr ? '（末次: ' + errMsg(lastErr) + '）' : ''));
  }
  return null;
}

// ------------------------------ LyricSyncer ------------------------------

// 同步层：无状态二分为主体；lastLine 记忆（最近一次 lines 引用 + index + 时刻）
// 提供热路径与 200ms 行切换滞回；seek（相邻查询时刻差 >1500ms 或 lines 引用变化）
// 直接采纳二分结果快速重定位。暂停联动：插件无播放器状态通道，宿主暂停期间
// 不推进 currentTime，本层自然停在当前行（文档已注明，无需额外状态）。
var _lyricSyncState = { lines: null, index: -1, time: 0 };

function lyricBinarySearch(lines, t) {
  var lo = 0;
  var hi = lines.length - 1;
  var ans = -1;
  while (lo <= hi) {
    var mid = (lo + hi) >> 1;
    if (lines[mid].time <= t) { ans = mid; lo = mid + 1; }
    else hi = mid - 1;
  }
  return ans;
}

/**
 * getCurrentLyricLine(currentTime, lines?)：
 *  - lines 缺省用最近一次 getLyric 解析缓存（缓存键 platform|id，TTL 10min、LRU 64）；
 *  - 返回 { index, line, prev, next, prev2, next2 }（当前行 + 前后各 2 行上下文；
 *    起始行之前 index=-1、line=null、next=首行）；
 *  - 200ms 滞回：前进跨入新行且距新行起始 <200ms 时维持当前行（快进快退的
 *    时刻抖动不致边界行频跳）；后退与 seek 即时重定位。
 */
function lyricSyncCurrentLine(currentTime, lines) {
  var t = Number(currentTime);
  if (isNaN(t)) t = 0;
  var src;
  if (lines === undefined || lines === null) {
    // 缺省：用最近一次 getLyric 解析缓存（缓存键 platform|id，TTL 10min、LRU 64）
    var cached = _lyricLastKey ? aggLruGet(_lyricCache, _lyricLastKey) : null;
    src = cached && cached.lines;
  } else {
    src = lines; // 显式传入（含空数组）：以调用方为准，不再回落缓存
  }
  if (!src || !src.length) return null;
  var idx = lyricBinarySearch(src, t);
  var st = _lyricSyncState;
  var isSeek = st.lines !== src || Math.abs(t - st.time) > AGG_LYRIC_SEEK_JUMP_MS;
  if (!isSeek && idx !== st.index && st.index >= 0 && idx === st.index + 1 &&
      src[idx] && (t - src[idx].time) < AGG_LYRIC_HYSTERESIS_MS) {
    idx = st.index; // 边界滞回：未越过新行起始 200ms，维持当前行
  }
  st.lines = src;
  st.index = idx;
  st.time = t;
  return {
    index: idx,
    line: idx >= 0 ? src[idx] : null,
    prev: idx >= 1 ? src[idx - 1] : null,
    next: idx + 1 < src.length ? src[idx + 1] : null,
    prev2: idx >= 2 ? src[idx - 2] : null,
    next2: idx + 2 < src.length ? src[idx + 2] : null
  };
}

