      normalizeAlbum: normalizeAlbum,
      detectArtistIntent: detectArtistIntent,
      normalizeItem: normalizeItem,
      editDistSim: editDistSim,
      artistSetSim: artistSetSim,
      softScoreOf: softScore,
      clusterAndMerge: clusterAndMerge,
      clusterBucketMembers: clusterBucketMembers,
      groupMatchScoreOf: groupMatchScore,
      groupSortScoreOf: groupSortScore,
      groupVersionScoreOf: groupVersionScore,
      versionClassOf: versionClassOf,
      versionRankOf: versionRankOf,
      buildMergedFinalItem: buildMergedFinalItem,
      // v1.3.0 聚合榜测试挂钩
      parseAggChartIdOf: parseAggChartId,
