      getMergedChartDetailOf: getMergedChartDetail,
      chartCache: _aggChartCache,
      chartCategories: CHART_CATEGORIES,
      servePageOf: servePage,
      searchPassthroughFn: searchPassthrough,
      searchCategoryAggregatedFn: searchCategoryAggregated,
      searchBudgetMsOf: searchBudgetMsOf,
      searchMaxPagesOf: searchMaxPagesOf,
      categoryAdaptRaw: categoryAdaptRaw,
